package gotests

import (
	"fmt"
	"go/ast"
	"go/format"
	"go/parser"
	"go/token"
	"os"
	"path/filepath"
	"regexp"
	"strings"

	"gotests/internal/input"
	"gotests/internal/render"
	"gotests/internal/output"
)

// Options controls test generation behavior
type Options struct {
	Only               string
	Excl               string
	Exported           bool
	PrintInputs        bool
	Named              bool
	Parallel           bool
	Subtests           bool
	WriteFiles         bool
	Template           string
	TemplateDir        string
	TemplateParamsFile string
	UseGoCmp           bool
}

// Run processes the given path (file or directory) and generates tests
func Run(path string, opts *Options) error {
	// Handle recursive pattern
	if strings.HasSuffix(path, "/...") {
		base := strings.TrimSuffix(path, "/...")
		return runRecursive(base, opts)
	}
	if path == "./..." {
		return runRecursive(".", opts)
	}
	if strings.HasSuffix(path, "...") {
		base := strings.TrimSuffix(path, "...")
		base = strings.TrimSuffix(base, "/")
		if base == "" {
			base = "."
		}
		return runRecursive(base, opts)
	}

	info, err := os.Stat(path)
	if err != nil {
		return fmt.Errorf("input.Files: os.Stat: %w", err)
	}

	if info.IsDir() {
		return runDir(path, opts)
	}
	return runFile(path, opts)
}

func runRecursive(base string, opts *Options) error {
	return filepath.Walk(base, func(path string, info os.FileInfo, err error) error {
		if err != nil {
			return err
		}
		if !info.IsDir() {
			return nil
		}
		// Skip hidden directories
		if path != base && strings.HasPrefix(filepath.Base(path), ".") {
			return filepath.SkipDir
		}
		return runDir(path, opts)
	})
}

func runDir(dir string, opts *Options) error {
	// Find all .go files (non-test) in the directory
	fset := token.NewFileSet()
	pkgs, err := parser.ParseDir(fset, dir, func(fi os.FileInfo) bool {
		name := fi.Name()
		return !strings.HasSuffix(name, "_test.go")
	}, 0)
	if err != nil {
		return fmt.Errorf("input.Files: %w", err)
	}

	// Find all existing test files
	existingTests := findExistingTests(dir)

	for _, pkg := range pkgs {
		for filename, file := range pkg.Files {
			if err := processFile(filename, fset, file, pkg.Name, existingTests, opts); err != nil {
				return err
			}
		}
	}
	return nil
}

func runFile(path string, opts *Options) error {
	fset := token.NewFileSet()
	file, err := parser.ParseFile(fset, path, nil, 0)
	if err != nil {
		return fmt.Errorf("input.Files: %w", err)
	}
	pkgName := file.Name.Name
	dir := filepath.Dir(path)
	existingTests := findExistingTests(dir)

	return processFile(path, fset, file, pkgName, existingTests, opts)
}

// findExistingTests returns a set of test function names from all test files in a directory
func findExistingTests(dir string) map[string]bool {
	existing := make(map[string]bool)
	fset := token.NewFileSet()
	pkgs, err := parser.ParseDir(fset, dir, func(fi os.FileInfo) bool {
		return strings.HasSuffix(fi.Name(), "_test.go")
	}, 0)
	if err != nil {
		return existing
	}
	for _, pkg := range pkgs {
		for _, file := range pkg.Files {
			for _, decl := range file.Decls {
				fn, ok := decl.(*ast.FuncDecl)
				if !ok {
					continue
				}
				existing[fn.Name.Name] = true
			}
		}
	}
	return existing
}

func matchFilter(name string, only, excl *regexp.Regexp, exported bool) bool {
	if excl != nil && excl.MatchString(name) {
		return false
	}
	if exported {
		if len(name) == 0 || name[0] < 'A' || name[0] > 'Z' {
			return false
		}
		return true
	}
	if only != nil {
		return only.MatchString(name)
	}
	return true // -all
}

func processFile(filename string, fset *token.FileSet, file *ast.File, pkgName string, existingTests map[string]bool, opts *Options) error {
	var onlyRe, exclRe *regexp.Regexp
	var err error
	if opts.Only != "" {
		onlyRe, err = regexp.Compile(opts.Only)
		if err != nil {
			return fmt.Errorf("invalid -only regexp: %w", err)
		}
	}
	if opts.Excl != "" {
		exclRe, err = regexp.Compile(opts.Excl)
		if err != nil {
			return fmt.Errorf("invalid -excl regexp: %w", err)
		}
	}

	// Collect functions/methods to test
	funcs := input.CollectFunctions(fset, file, func(name string) bool {
		if exclRe != nil {
			return matchFilter(name, onlyRe, exclRe, opts.Exported)
		}
		if opts.Exported {
			return matchFilter(name, onlyRe, nil, true)
		}
		if onlyRe != nil {
			return matchFilter(name, onlyRe, nil, false)
		}
		return true // -all
	})

	// Filter out existing tests
	var newFuncs []*input.Function
	for _, fn := range funcs {
		testName := fn.TestName()
		if !existingTests[testName] {
			newFuncs = append(newFuncs, fn)
		}
	}

	if len(newFuncs) == 0 {
		if !opts.WriteFiles {
			fmt.Printf("No tests generated for %s\n", filename)
		} else {
			fmt.Printf("No tests generated for %s\n", filename)
		}
		return nil
	}

	// Generate test code
	testFile := testFilename(filename)

	// Parse existing test file if it exists
	var existingFile *ast.File
	var existingFset = token.NewFileSet()
	if _, statErr := os.Stat(testFile); statErr == nil {
		existingFile, _ = parser.ParseFile(existingFset, testFile, nil, parser.ParseComments)
	}

	renderOpts := &render.Options{
		PrintInputs:        opts.PrintInputs,
		Named:              opts.Named,
		Parallel:           opts.Parallel,
		Subtests:           opts.Subtests,
		Template:           opts.Template,
		TemplateDir:        opts.TemplateDir,
		TemplateParamsFile: opts.TemplateParamsFile,
		UseGoCmp:           opts.UseGoCmp,
	}

	// Print generated names
	for _, fn := range newFuncs {
		fmt.Printf("Generated %s\n", fn.TestName())
	}

	generated, err := render.GenerateTests(pkgName, newFuncs, existingFile, existingFset, renderOpts)
	if err != nil {
		return fmt.Errorf("render: %w", err)
	}

	// Format
	formatted, err := format.Source(generated)
	if err != nil {
		return fmt.Errorf("format: %w\n%s", err, string(generated))
	}

	if opts.WriteFiles {
		return output.WriteFile(testFile, formatted)
	}
	fmt.Print(string(formatted))
	return nil
}

func testFilename(goFile string) string {
	base := filepath.Base(goFile)
	ext := filepath.Ext(base)
	name := base[:len(base)-len(ext)]
	return filepath.Join(filepath.Dir(goFile), name+"_test.go")
}
EOF

