cat > /workspace/gotests/internal/input/input.go << 'GOEOF'
package input

import (
	"go/ast"
	"go/token"
	"strings"
	"unicode"
)

// Param represents a function parameter
type Param struct {
	Name     string
	Type     string
	IsVariadic bool
}

// ReturnValue represents a function return value
type ReturnValue struct {
	Name string
	Type string
}

// Function represents a parsed Go function or method
type Function struct {
	Name       string
	Receiver   *Receiver
	Params     []*Param
	Returns    []*ReturnValue
	ReturnsErr bool
	// For error-only returns
	OnlyError bool
}

// Receiver represents a method receiver
type Receiver struct {
	Name   string // variable name
	Type   string // type name (without pointer)
	IsPtr  bool   // is pointer receiver
	Fields []*Field // struct fields
}

// Field represents a struct field  
type Field struct {
	Name string
	Type string
}

// TestName returns the test function name for this function
func (f *Function) TestName() string {
	if f.Receiver != nil {
		return "Test" + f.Receiver.Type + "_" + f.Name
	}
	// Unexported functions use Test_ prefix
	if len(f.Name) > 0 && unicode.IsLower(rune(f.Name[0])) {
		return "Test_" + f.Name
	}
	return "Test" + f.Name
}

// ReceiverVarName returns the variable name for the receiver in tests
func (f *Function) ReceiverVarName() string {
	if f.Receiver == nil {
		return ""
	}
	if f.Receiver.Name != "" {
		return f.Receiver.Name
	}
	// Use first letter of type name (lowercased)
	if len(f.Receiver.Type) > 0 {
		return strings.ToLower(string(f.Receiver.Type[0]))
	}
	return "r"
}

// CollectFunctions collects all functions from a file that match the filter
func CollectFunctions(fset *token.FileSet, file *ast.File, filter func(string) bool) []*Function {
	// Build type map for struct fields
	typeMap := buildTypeMap(file)

	var funcs []*Function
	for _, decl := range file.Decls {
		fn, ok := decl.(*ast.FuncDecl)
		if !ok {
			continue
		}
		if !filter(fn.Name.Name) {
			continue
		}

		f := parseFunction(fset, file, fn, typeMap)
		funcs = append(funcs, f)
	}
	return funcs
}

type structInfo struct {
	fields []*Field
}

func buildTypeMap(file *ast.File) map[string]*structInfo {
	m := make(map[string]*structInfo)
	for _, decl := range file.Decls {
		gd, ok := decl.(*ast.GenDecl)
		if !ok {
			continue
		}
		for _, spec := range gd.Specs {
			ts, ok := spec.(*ast.TypeSpec)
			if !ok {
				continue
			}
			st, ok := ts.Type.(*ast.StructType)
			if !ok {
				continue
			}
			si := &structInfo{}
			if st.Fields != nil {
				for _, field := range st.Fields.List {
					typeStr := typeExprToString(field.Type)
					if len(field.Names) == 0 {
						// Embedded field
						si.fields = append(si.fields, &Field{Name: typeStr, Type: typeStr})
					} else {
						for _, name := range field.Names {
							si.fields = append(si.fields, &Field{Name: name.Name, Type: typeStr})
						}
					}
				}
			}
			m[ts.Name.Name] = si
		}
	}
	return m
}

func parseFunction(fset *token.FileSet, file *ast.File, fn *ast.FuncDecl, typeMap map[string]*structInfo) *Function {
	f := &Function{
		Name: fn.Name.Name,
	}

	// Parse receiver
	if fn.Recv != nil && len(fn.Recv.List) > 0 {
		recvField := fn.Recv.List[0]
		recv := &Receiver{}

		var recvTypeName string
		var isPtr bool

		switch t := recvField.Type.(type) {
		case *ast.StarExpr:
			isPtr = true
			switch inner := t.X.(type) {
			case *ast.Ident:
				recvTypeName = inner.Name
			case *ast.IndexExpr:
				// Generic type like Set[T]
				if id, ok := inner.X.(*ast.Ident); ok {
					recvTypeName = id.Name
				}
			case *ast.IndexListExpr:
				if id, ok := inner.X.(*ast.Ident); ok {
					recvTypeName = id.Name
				}
			}
		case *ast.Ident:
			isPtr = false
			recvTypeName = t.Name
		case *ast.IndexExpr:
			if id, ok := t.X.(*ast.Ident); ok {
				recvTypeName = id.Name
			}
		case *ast.IndexListExpr:
			if id, ok := t.X.(*ast.Ident); ok {
				recvTypeName = id.Name
			}
		}

		recv.Type = recvTypeName
		recv.IsPtr = isPtr

		// Get receiver variable name
		if len(recvField.Names) > 0 {
			recv.Name = recvField.Names[0].Name
		} else {
			// Use first letter of type name
			if len(recvTypeName) > 0 {
				recv.Name = strings.ToLower(string(recvTypeName[0]))
			}
		}

		// Get struct fields
		if si, ok := typeMap[recvTypeName]; ok {
			recv.Fields = si.fields
		}

		f.Receiver = recv
	}

	// Parse parameters
	if fn.Type.Params != nil {
		for _, field := range fn.Type.Params.List {
			isVariadic := false
			typeStr := ""
			if ve, ok := field.Type.(*ast.Ellipsis); ok {
				isVariadic = true
				typeStr = "[]" + typeExprToString(ve.Elt)
			} else {
				typeStr = typeExprToString(field.Type)
			}

			if len(field.Names) == 0 {
				// Unnamed parameter
				f.Params = append(f.Params, &Param{
					Name:       paramName(typeStr, len(f.Params)),
					Type:       typeStr,
					IsVariadic: isVariadic,
				})
			} else {
				for _, name := range field.Names {
					f.Params = append(f.Params, &Param{
						Name:       name.Name,
						Type:       typeStr,
						IsVariadic: isVariadic,
					})
				}
			}
		}
	}

	// Parse return values
	if fn.Type.Results != nil {
		results := fn.Type.Results.List
		for i, field := range results {
			typeStr := typeExprToString(field.Type)
			isErr := typeStr == "error"

			if len(field.Names) == 0 {
				if isErr && i == len(results)-1 {
					f.ReturnsErr = true
					if len(results) == 1 {
						f.OnlyError = true
					}
				} else {
					retName := ""
					if len(results) == 1 {
						retName = "want"
					} else {
						if i == 0 {
							retName = "want"
						} else {
							retName = "want" + string(rune('0'+i))
						}
					}
					f.Returns = append(f.Returns, &ReturnValue{
						Name: retName,
						Type: typeStr,
					})
				}
			} else {
				for _, name := range field.Names {
					if isErr {
						f.ReturnsErr = true
						if len(results) == 1 {
							f.OnlyError = true
						}
					} else {
						// Named return: "wantFoo" where Foo is capitalized name
						retName := "want" + strings.Title(name.Name)
						f.Returns = append(f.Returns, &ReturnValue{
							Name: retName,
							Type: typeStr,
						})
					}
				}
			}
		}
	}

	return f
}

func paramName(typeStr string, idx int) string {
	// Generate a simple name based on type
	switch typeStr {
	case "int", "int8", "int16", "int32", "int64",
		"uint", "uint8", "uint16", "uint32", "uint64",
		"float32", "float64", "complex64", "complex128",
		"byte", "rune", "bool", "string":
		return strings.ToLower(string(typeStr[0]))
	}
	if len(typeStr) > 0 {
		return strings.ToLower(string(typeStr[0]))
	}
	return fmt.Sprintf("arg%d", idx)
