		buf.WriteString("import (\n")
		for _, imp := range allImports {
			buf.WriteString("\t")
			buf.WriteString(imp)
			buf.WriteString("\n")
		}
		buf.WriteString(")\n")
	}

	// Write existing functions if any
	if existingFile != nil {
		existingCode := extractExistingFunctions(existingFile, existingFset)
		if existingCode != "" {
			buf.WriteString("\n")
			buf.WriteString(existingCode)
		}
	}

	// Write new test functions
	for _, fn := range funcs {
		buf.WriteString("\n")
		testCode, err := renderFunction(fn, opts, useReflect || useGoCmp || useTestify)
		if err != nil {
			return nil, err
		}
		buf.Write(testCode)
	}

	return buf.Bytes(), nil
}

func collectExistingImports(file *ast.File) []string {
	if file == nil {
