// resolveConstraintType maps a type constraint to a concrete type for testing
func resolveConstraintType(constraint string) string {
	switch constraint {
	case "any":
		return "int"
	case "comparable":
		return "string"
	}
	// Check for approximation: ~int → int
	if strings.HasPrefix(constraint, "~") {
		return resolveConstraintType(constraint[1:])
	}
	// Check for inline union: int64 | float64 → int64 (first option)
	if strings.Contains(constraint, " | ") {
		parts := strings.SplitN(constraint, " | ", 2)
		return resolveConstraintType(strings.TrimSpace(parts[0]))
	}
	// Named interface or other types → use string (like comparable)
	// Check if it's a known primitive
	switch constraint {
	case "int", "int8", "int16", "int32", "int64",
