package input

import (
	"go/ast"
	"go/token"
	"strings"
)

// Param represents a function parameter
type Param struct {
	Name       string
	Type       string
	IsVariadic bool
}

// ReturnValue represents a function return value  
type ReturnValue struct {
	Name string // "want", "want1", "wantFoo" etc.
	Type string
}

// Field represents a struct field
type Field struct {
	Name string
	Type string
}

// Receiver represents a method receiver
type Receiver struct {
	Name   string   // variable name used in the function
	Type   string   // type name (without * and generic params)
	IsPtr  bool     // is pointer receiver
	Fields []*Field // struct fields (empty if no fields)
}

// Function represents a parsed Go function or method
type Function struct {
	Name        string
	Receiver    *Receiver
	Params      []*Param
	Returns     []*ReturnValue
	ReturnsErr  bool   // has an error return (but not only error)
	OnlyError   bool   // only returns error
	TypeParams  []string // generic type parameter names for instantiation
}

// TestName returns the expected test function name
func (f *Function) TestName() string {
	if f.Receiver != nil {
		return "Test" + f.Receiver.Type + "_" + f.Name
	}
	if len(f.Name) > 0 {
		c := f.Name[0]
		if c >= 'a' && c <= 'z' {
			return "Test_" + f.Name
		}
	}
	return "Test" + f.Name
}

// HasArgs returns true if the function has parameters
func (f *Function) HasArgs() bool {
	return len(f.Params) > 0
}

// HasResults returns true if the function has non-error return values
func (f *Function) HasResults() bool {
	return len(f.Returns) > 0
}

// ReceiverHasFields returns true if the receiver struct has exported or unexported fields
func (f *Function) ReceiverHasFields() bool {
	return f.Receiver != nil && len(f.Receiver.Fields) > 0
}

// CollectFunctions parses a Go source file and collects functions matching the filter
func CollectFunctions(fset *token.FileSet, file *ast.File, filter func(string) bool) []*Function {
	typeMap := buildTypeMap(file)
	typeParamMap := buildTypeParamMap(file)
	_ = fset // may use later for source positions

	var funcs []*Function
	for _, decl := range file.Decls {
		fn, ok := decl.(*ast.FuncDecl)
		if !ok {
			continue
		}
		if !filter(fn.Name.Name) {
			continue
		}
		f := parseFunction(fn, typeMap, typeParamMap)
		funcs = append(funcs, f)
	}
	return funcs
}

type structInfo struct {
	fields []*Field
}

// buildTypeMap builds a map of struct type names to their fields
func buildTypeMap(file *ast.File) map[string]*structInfo {
	m := make(map[string]*structInfo)
	for _, decl := range file.Decls {
		gd, ok := decl.(*ast.GenDecl)
		if !ok {
			continue
		}
		for _, spec := range gd.Specs {
			ts, ok := spec.(*ast.TypeSpec)
			if !ok {
				continue
			}
			st, ok := ts.Type.(*ast.StructType)
			if !ok {
				continue
			}
			si := &structInfo{}
			if st.Fields != nil {
				for _, field := range st.Fields.List {
					typeStr := TypeExprToString(field.Type)
					if len(field.Names) == 0 {
						// Embedded field
						name := typeStr
						// strip package prefix if any
						if idx := strings.LastIndex(name, "."); idx >= 0 {
							name = name[idx+1:]
						}
						// strip pointer
						name = strings.TrimPrefix(name, "*")
						si.fields = append(si.fields, &Field{Name: name, Type: typeStr})
					} else {
						for _, n := range field.Names {
							si.fields = append(si.fields, &Field{Name: n.Name, Type: typeStr})
						}
					}
				}
			}
			m[ts.Name.Name] = si
		}
	}
	return m
}

// buildTypeParamMap builds a map of type names to their type parameter constraints
func buildTypeParamMap(file *ast.File) map[string][]string {
	m := make(map[string][]string)
	for _, decl := range file.Decls {
		gd, ok := decl.(*ast.GenDecl)
		if !ok {
			continue
		}
		for _, spec := range gd.Specs {
			ts, ok := spec.(*ast.TypeSpec)
			if !ok {
				continue
			}
			if ts.TypeParams == nil {
				continue
			}
			for _, field := range ts.TypeParams.List {
				for range field.Names {
					constraint := TypeExprToString(field.Type)
					m[ts.Name.Name] = append(m[ts.Name.Name], constraint)
