		if len(ft.Results.List) == 1 && len(ft.Results.List[0].Names) == 0 {
			sb.WriteString(" ")
			sb.WriteString(TypeExprToString(ft.Results.List[0].Type))
		} else {
			sb.WriteString(" (")
			first := true
			for _, field := range ft.Results.List {
				typeStr := TypeExprToString(field.Type)
				count := 1
				if len(field.Names) > 0 {
					count = len(field.Names)
				}
				for i := 0; i < count; i++ {
					if !first {
						sb.WriteString(", ")
					}
					sb.WriteString(typeStr)
					first = false
				}
			}
			sb.WriteString(")")
		}
	}
	return sb.String()
}

func structTypeToString(st *ast.StructType) string {
	var sb strings.Builder
	sb.WriteString("struct{")
	if st.Fields != nil {
		fields := []string{}
		for _, field := range st.Fields.List {
			typeStr := TypeExprToString(field.Type)
			if len(field.Names) == 0 {
				fields = append(fields, typeStr)
			} else {
				names := make([]string, len(field.Names))
				for i, n := range field.Names {
					names[i] = n.Name
				}
				fields = append(fields, strings.Join(names, ", ")+" "+typeStr)
			}
		}
		sb.WriteString(strings.Join(fields, "; "))
	}
	sb.WriteString("}")
	return sb.String()
}
GOEOF

