# So the existing function IS reformatted (by gofmt)
# The content is preserved but whitespace is normalized
# And the import "reflect" was added to the imports section

# The approach for handling existing files:
# 1. Parse the AST of the existing test file
# 2. Extract all existing function bodies/declarations
# 3. Add new imports
# 4. Reconstruct the file with existing functions + new test functions
# 5. Run gofmt on the result

# Let me understand how existing functions are preserved:
# The tool uses the AST printer to reprint existing functions
# This naturally applies gofmt-like formatting

# Now let me write the complete render package

cat > /workspace/gotests/internal/render/render.go << 'GOEOF'
package render

import (
	"bytes"
	"fmt"
	"go/ast"
	"go/format"
	"go/printer"
	"go/token"
	"strings"

	"gotests/internal/input"
)

// Options for rendering
type Options struct {
	PrintInputs        bool
	Named              bool
	Parallel           bool
	Subtests           bool
	Template           string
	TemplateDir        string
	TemplateParamsFile string
	UseGoCmp           bool
}

// GenerateTests generates test code for the given functions
// existingFile is the parsed existing test file (may be nil)
func GenerateTests(pkgName string, funcs []*input.Function, existingFile *ast.File, existingFset *token.FileSet, opts *Options) ([]byte, error) {
	useTestify := opts.Template == "testify"
	useGoCmp := opts.UseGoCmp

	// Determine needed imports
	needReflect := false
	if !useGoCmp && !useTestify {
		for _, fn := range funcs {
			if needsReflectDeepEqual(fn) {
				needReflect = true
				break
			}
		}
		// Also check existing file's needs
		if existingFile != nil {
			for _, imp := range existingFile.Imports {
				if imp.Path.Value == `"reflect"` {
					needReflect = true
					break
				}
			}
		}
	}

	needFmt := false
	if useTestify && !opts.Subtests {
		for _, fn := range funcs {
			if fn.ReturnsErr && !fn.OnlyError {
				needFmt = true
				break
			}
		}
		// Check existing file
		if existingFile != nil {
			for _, imp := range existingFile.Imports {
				if imp.Path.Value == `"fmt"` {
					needFmt = true
					break
				}
			}
		}
	}

	// Build the source
	var buf bytes.Buffer

	// Package declaration
	buf.WriteString("package ")
	buf.WriteString(pkgName)
	buf.WriteString("\n\n")

	// Determine all imports
	importSet := make(map[string]bool)
	importOrder := []string{}

	addImport := func(path string) {
		if !importSet[path] {
			importSet[path] = true
			importOrder = append(importOrder, path)
		}
	}

	// Add imports from existing file first
	if existingFile != nil {
		for _, imp := range existingFile.Imports {
			path := imp.Path.Value
			if imp.Name != nil {
				path = imp.Name.Name + " " + path
			}
			addImport(path)
		}
	}

	// Add new imports
	if needFmt {
		addImport(`"fmt"`)
	}
	addImport(`"testing"`)
	if needReflect {
		addImport(`"reflect"`)
	}
	if useGoCmp {
		addImport(`"github.com/google/go-cmp/cmp"`)
	}
	if useTestify {
		addImport(`"github.com/stretchr/testify/assert"`)
	}

	// Write imports
	if len(importOrder) == 1 {
		buf.WriteString("import ")
		buf.WriteString(importOrder[0])
		buf.WriteString("\n")
	} else if len(importOrder) > 1 {
		buf.WriteString("import (\n")
		for _, imp := range importOrder {
			buf.WriteString("\t")
			buf.WriteString(imp)
			buf.WriteString("\n")
		}
		buf.WriteString(")\n")
	}

	// Write existing test functions (if any)
	if existingFile != nil {
		for _, decl := range existingFile.Decls {
			fn, ok := decl.(*ast.FuncDecl)
			if !ok {
				continue
			}
			buf.WriteString("\n")
			if err := printer.Fprint(&buf, existingFset, fn); err != nil {
				return nil, fmt.Errorf("print existing function: %w", err)
			}
			buf.WriteString("\n")
		}
	}

	// Write new test functions
	for _, fn := range funcs {
		buf.WriteString("\n")
		testCode := renderTestFunction(fn, opts, needReflect, useGoCmp, useTestify)
		buf.WriteString(testCode)
		buf.WriteString("\n")
	}

	// Apply gofmt
	formatted, err := format.Source(buf.Bytes())
	if err != nil {
		return buf.Bytes(), nil // return unformatted, caller will handle error
	}
	return formatted, nil
}

// needsReflectDeepEqual returns true if the function's returns need reflect.DeepEqual
func needsReflectDeepEqual(fn *input.Function) bool {
	for _, ret := range fn.Returns {
		if isComplexType(ret.Type) {
			return true
		}
	}
	return false
}

// isComplexType returns true for types that need reflect.DeepEqual (not comparable with ==)
func isComplexType(t string) bool {
	switch t {
	case "bool", "string", "error",
		"int", "int8", "int16", "int32", "int64",
		"uint", "uint8", "uint16", "uint32", "uint64",
		"uintptr", "float32", "float64",
		"complex64", "complex128",
		"byte", "rune":
		return false
	}
	return true
}

// renderTestFunction generates the test function code
func renderTestFunction(fn *input.Function, opts *Options, needReflect, useGoCmp, useTestify bool) string {
	var sb strings.Builder

	testName := fn.TestName()
	recvName := ""
	if fn.Receiver != nil {
		recvName = fn.Receiver.Name
	}

	// Determine comparison function
	useDeepEqual := !useGoCmp && !useTestify

	sb.WriteString("func ")
	sb.WriteString(testName)
	sb.WriteString("(t *testing.T) {\n")

	// Optional parallel
	if opts.Parallel {
		sb.WriteString("\tt.Parallel()\n")
	}

	// Fields struct (for receiver with fields)
	if fn.ReceiverHasFields() {
		sb.WriteString("\ttype fields struct {\n")
		for _, f := range fn.Receiver.Fields {
			sb.WriteString("\t\t")
			sb.WriteString(f.Name)
			sb.WriteString(" ")
			sb.WriteString(f.Type)
			sb.WriteString("\n")
		}
		sb.WriteString("\t}\n")
	}

	// Args struct (if has params)
	if fn.HasArgs() {
		sb.WriteString("\ttype args struct {\n")
		for _, p := range fn.Params {
			sb.WriteString("\t\t")
			sb.WriteString(p.Name)
			sb.WriteString(" ")
			sb.WriteString(p.Type)
			sb.WriteString("\n")
		}
		sb.WriteString("\t}\n")
	}

	// Test cases struct
	if opts.Named {
		// Map-based tests
		sb.WriteString("\ttests := map[string]struct {\n")
	} else {
		// Slice-based tests
		sb.WriteString("\ttests := []struct {\n")
		if !opts.Named {
			sb.WriteString("\t\tname string\n")
		}
	}

	// Receiver field in test struct (if no fields struct)
	if fn.Receiver != nil && !fn.ReceiverHasFields() {
		sb.WriteString("\t\t")
		sb.WriteString(recvName)
		sb.WriteString(" ")
		if fn.Receiver.IsPtr {
			sb.WriteString("*")
		}
		sb.WriteString(fn.Receiver.Type)
		if len(fn.TypeParams) > 0 {
			sb.WriteString("[")
			for i, tp := range fn.TypeParams {
				if i > 0 {
					sb.WriteString(", ")
				}
				sb.WriteString(tp)
			}
			sb.WriteString("]")
		}
		sb.WriteString("\n")
	}

	// Fields field in test struct (if has fields)
	if fn.ReceiverHasFields() {
		sb.WriteString("\t\tfields fields\n")
	}

	// Args field in test struct
	if fn.HasArgs() {
		sb.WriteString("\t\targs args\n")
	}

	// Return values in test struct
	if fn.OnlyError {
		if useTestify {
			sb.WriteString("\t\tassertion assert.ErrorAssertionFunc\n")
		} else {
			sb.WriteString("\t\twantErr bool\n")
		}
	} else if fn.ReturnsErr {
		if useTestify {
			// Returns + assertion
			for _, ret := range fn.Returns {
				sb.WriteString("\t\t")
				sb.WriteString(ret.Name)
				sb.WriteString(" ")
				sb.WriteString(ret.Type)
				sb.WriteString("\n")
			}
			sb.WriteString("\t\tassertion assert.ErrorAssertionFunc\n")
		} else {
			for _, ret := range fn.Returns {
				sb.WriteString("\t\t")
				sb.WriteString(ret.Name)
				sb.WriteString(" ")
				sb.WriteString(ret.Type)
				sb.WriteString("\n")
			}
			sb.WriteString("\t\twantErr bool\n")
		}
	} else {
		// No error returns
		for _, ret := range fn.Returns {
			sb.WriteString("\t\t")
			sb.WriteString(ret.Name)
			sb.WriteString(" ")
			sb.WriteString(ret.Type)
			sb.WriteString("\n")
		}
	}

	sb.WriteString("\t}{\n")
	sb.WriteString("\t\t// TODO: Add test cases.\n")
	sb.WriteString("\t}\n")

	// Loop
	if opts.Named {
		sb.WriteString("\tfor name, tt := range tests {\n")
	} else {
		sb.WriteString("\tfor _, tt := range tests {\n")
	}

	if opts.Subtests {
		// With subtests
		if opts.Named {
			sb.WriteString("\t\tt.Run(name, func(t *testing.T) {\n")
		} else {
			sb.WriteString("\t\tt.Run(tt.name, func(t *testing.T) {\n")
		}
		if opts.Parallel {
			sb.WriteString("\t\t\tt.Parallel()\n")
		}

		// Setup receiver
		setupReceiver(&sb, fn, recvName, "\t\t\t")

		// Function call and assertions
		renderCallAndAssert(&sb, fn, opts, recvName, useDeepEqual, useGoCmp, useTestify, "\t\t\t", false)

		sb.WriteString("\t\t})\n")
	} else {
		// Without subtests
		// Setup receiver
		setupReceiver(&sb, fn, recvName, "\t\t")

		// Function call and assertions (nosubtests version)
		renderCallAndAssert(&sb, fn, opts, recvName, useDeepEqual, useGoCmp, useTestify, "\t\t", true)
	}

	sb.WriteString("\t}\n")
	sb.WriteString("}")

	return sb.String()
}

// setupReceiver writes the receiver setup code
func setupReceiver(sb *strings.Builder, fn *input.Function, recvName, indent string) {
	if fn.Receiver == nil {
		return
	}

	typeName := fn.Receiver.Type
	typeParams := ""
	if len(fn.TypeParams) > 0 {
		parts := make([]string, len(fn.TypeParams))
		copy(parts, fn.TypeParams)
		typeParams = "[" + strings.Join(parts, ", ") + "]"
	}

	if fn.ReceiverHasFields() {
		// Initialize receiver with fields from test struct
		sb.WriteString(indent)
		sb.WriteString(recvName)
		sb.WriteString(" := ")
		if fn.Receiver.IsPtr {
			sb.WriteString("&")
		}
		sb.WriteString(typeName)
		sb.WriteString(typeParams)
		sb.WriteString("{\n")
		for _, f := range fn.Receiver.Fields {
			sb.WriteString(indent)
			sb.WriteString("\t")
			sb.WriteString(f.Name)
			sb.WriteString(": tt.fields.")
			sb.WriteString(f.Name)
			sb.WriteString(",\n")
		}
		sb.WriteString(indent)
		sb.WriteString("}\n")
	} else {
		// Initialize receiver without fields
		sb.WriteString(indent)
		sb.WriteString(recvName)
		sb.WriteString(" := ")
		if fn.Receiver.IsPtr {
			sb.WriteString("&")
		}
		sb.WriteString(typeName)
		sb.WriteString(typeParams)
		sb.WriteString("{}\n")
	}
}

// functionCallStr generates the function call string
func functionCallStr(fn *input.Function, recvName string) string {
	var sb strings.Builder

	// Receiver or function name
	if fn.Receiver != nil {
		sb.WriteString(recvName)
		sb.WriteString(".")
		sb.WriteString(fn.Name)
	} else {
		sb.WriteString(fn.Name)
		// Type params for generic functions
		if len(fn.TypeParams) > 0 {
			sb.WriteString("[")
			for i, tp := range fn.TypeParams {
				if i > 0 {
					sb.WriteString(", ")
				}
				sb.WriteString(tp)
			}
			sb.WriteString("]")
		}
	}

	sb.WriteString("(")
	for i, p := range fn.Params {
		if i > 0 {
			sb.WriteString(", ")
		}
		sb.WriteString("tt.args.")
		sb.WriteString(p.Name)
		if p.IsVariadic {
			sb.WriteString("...")
		}
	}
	sb.WriteString(")")

	return sb.String()
}

// functionNameStr returns "FuncName()" for error messages
func functionNameStr(fn *input.Function) string {
	if fn.Receiver != nil {
		return fn.Receiver.Type + "." + fn.Name + "()"
	}
	return fn.Name + "()"
}

// inputArgsStr returns format string for printing inputs
func inputArgsStr(fn *input.Function) string {
	if len(fn.Params) == 0 {
		return ""
	}
	parts := make([]string, len(fn.Params))
	for i, p := range fn.Params {
		parts[i] = "tt.args." + p.Name
	}
	return strings.Join(parts, ", ")
}

// inputFormatStr returns "%v, %v" style format string for args
func inputFormatStr(fn *input.Function) string {
	if len(fn.Params) == 0 {
		return ""
	}
	parts := make([]string, len(fn.Params))
	for range parts {
		parts[len(parts)-len(parts)] = "%v"
	}
	for i := range fn.Params {
		parts[i] = "%v"
	}
	return strings.Join(parts, ", ")
}

// renderCallAndAssert writes the function call and assertion code
func renderCallAndAssert(sb *strings.Builder, fn *input.Function, opts *Options, recvName string, useDeepEqual, useGoCmp, useTestify bool, indent string, noSubtests bool) {
	callStr := functionCallStr(fn, recvName)
	fnName := functionNameStr(fn)

	// Build input args string for -i flag
	inputArgs := inputArgsStr(fn)
	inputFmt := inputFormatStr(fn)

	hasInputs := opts.PrintInputs && len(fn.Params) > 0

	if fn.OnlyError {
		// Only error return: if err := Fn(); (err != nil) != tt.wantErr
		if useTestify {
			if noSubtests {
				sb.WriteString(indent)
				sb.WriteString("tt.assertion(t, ")
				sb.WriteString(callStr)
				sb.WriteString(", fmt.Sprintf(\"%q. ")
				sb.WriteString(fn.Name + "()")
				if hasInputs {
					sb.WriteString("(")
					sb.WriteString(inputFmt)
					sb.WriteString(")")
					_ = inputArgs
				}
				sb.WriteString("\", tt.name")
				if hasInputs {
					sb.WriteString(", " + inputArgs)
				}
				sb.WriteString("))\n")
			} else {
				sb.WriteString(indent)
				sb.WriteString("tt.assertion(t, ")
				sb.WriteString(callStr)
				if hasInputs {
					sb.WriteString(fmt.Sprintf(", fmt.Sprintf(\"%s(%s)\", %s)", fn.Name+"()", inputFmt, inputArgs))
				}
				sb.WriteString(")\n")
			}
		} else {
			if noSubtests {
				sb.WriteString(indent)
				sb.WriteString("if err := ")
				sb.WriteString(callStr)
				sb.WriteString("; (err != nil) != tt.wantErr {\n")
				sb.WriteString(indent + "\t")
				if hasInputs {
					sb.WriteString(fmt.Sprintf("t.Errorf(\"%%q. %s(%s) error = %%v, wantErr %%v\", tt.name, %s, err, tt.wantErr)\n", fn.Name, inputFmt, inputArgs))
				} else {
					sb.WriteString(fmt.Sprintf("t.Errorf(\"%%q. %s error = %%v, wantErr %%v\", tt.name, err, tt.wantErr)\n", fnName))
				}
				sb.WriteString(indent + "}\n")
			} else {
				sb.WriteString(indent)
				sb.WriteString("if err := ")
				sb.WriteString(callStr)
				sb.WriteString("; (err != nil) != tt.wantErr {\n")
				sb.WriteString(indent + "\t")
				if hasInputs {
					sb.WriteString(fmt.Sprintf("t.Errorf(\"%s(%s) error = %%v, wantErr %%v\", %s, err, tt.wantErr)\n", fn.Name, inputFmt, inputArgs))
				} else {
					sb.WriteString(fmt.Sprintf("t.Errorf(\"%s error = %%v, wantErr %%v\", err, tt.wantErr)\n", fnName))
				}
				sb.WriteString(indent + "}\n")
			}
		}
		return
	}

	if !fn.HasResults() && !fn.ReturnsErr && !fn.OnlyError {
		// No returns at all - just call the function
		sb.WriteString(indent)
		sb.WriteString(callStr)
		sb.WriteString("\n")
		return
	}

	// Build variable assignment for returns
	// Returns list (non-error)
	var gotVars []string
	for i, ret := range fn.Returns {
		var gotName string
		if ret.Name == "want" {
			gotName = "got"
		} else if ret.Name == "want1" {
			gotName = "got1"
		} else if strings.HasPrefix(ret.Name, "want") && len(ret.Name) > 4 {
			// Named return: wantFoo → gotFoo
			suffix := ret.Name[4:] // "Foo"
			gotName = "got" + suffix
		} else {
			gotName = fmt.Sprintf("got%d", i)
		}
		gotVars = append(gotVars, gotName)
	}

	if fn.ReturnsErr {
		// Has both error and non-error returns
		allVars := append(append([]string{}, gotVars...), "err")

		if useTestify {
			// testify: got, err := Fn(); tt.assertion(t, err); assert.Equal(t, tt.want, got)
			sb.WriteString(indent)
			sb.WriteString(strings.Join(allVars, ", "))
			sb.WriteString(" := ")
			sb.WriteString(callStr)
			sb.WriteString("\n")

			if noSubtests {
				sb.WriteString(indent)
				sb.WriteString("tt.assertion(t, err, fmt.Sprintf(\"%q. ")
				sb.WriteString(fn.Name + "()")
				if hasInputs {
					sb.WriteString("(")
					sb.WriteString(inputFmt)
					sb.WriteString(")")
				}
				sb.WriteString("\", tt.name")
				if hasInputs {
					sb.WriteString(", " + inputArgs)
				}
				sb.WriteString("))\n")
			} else {
				sb.WriteString(indent)
				sb.WriteString("tt.assertion(t, err")
				if hasInputs {
					sb.WriteString(fmt.Sprintf(", fmt.Sprintf(\"%s(%s)\", %s)", fn.Name+"()", inputFmt, inputArgs))
				}
				sb.WriteString(")\n")
			}

			for i, ret := range fn.Returns {
				gotVar := gotVars[i]
				if noSubtests {
					if isComplexType(ret.Type) {
						if useGoCmp {
							sb.WriteString(indent)
							sb.WriteString(fmt.Sprintf("// TODO: assert %s\n", gotVar))
						} else {
							sb.WriteString(indent)
							sb.WriteString(fmt.Sprintf("assert.Equalf(t, tt.%s, %s, \"%%q. %s()\", tt.name)\n", ret.Name, gotVar, fn.Name))
						}
					} else {
						sb.WriteString(indent)
						if hasInputs {
							sb.WriteString(fmt.Sprintf("assert.Equalf(t, tt.%s, %s, \"%%q. %s(%s)\", tt.name, %s)\n", ret.Name, gotVar, fn.Name, inputFmt, inputArgs))
						} else {
							sb.WriteString(fmt.Sprintf("assert.Equalf(t, tt.%s, %s, \"%%q. %s()\", tt.name)\n", ret.Name, gotVar, fn.Name))
						}
					}
				} else {
					sb.WriteString(indent)
					if hasInputs {
						sb.WriteString(fmt.Sprintf("assert.Equalf(t, tt.%s, %s, \"%s(%s)\", %s)\n", ret.Name, gotVar, fn.Name+"()", inputFmt, inputArgs))
					} else {
						sb.WriteString(fmt.Sprintf("assert.Equal(t, tt.%s, %s)\n", ret.Name, gotVar))
					}
				}
			}
		} else {
			// Standard: got, err := Fn(); Fatalf/Errorf; if got != tt.want
			sb.WriteString(indent)
			sb.WriteString(strings.Join(allVars, ", "))
			sb.WriteString(" := ")
			sb.WriteString(callStr)
			sb.WriteString("\n")

			// Error check
			sb.WriteString(indent)
			sb.WriteString("if (err != nil) != tt.wantErr {\n")
			sb.WriteString(indent + "\t")
			if noSubtests {
				if hasInputs {
					sb.WriteString(fmt.Sprintf("t.Errorf(\"%%q. %s(%s) error = %%v, wantErr %%v\", tt.name, %s, err, tt.wantErr)\n", fn.Name, inputFmt, inputArgs))
				} else {
					sb.WriteString(fmt.Sprintf("t.Errorf(\"%%q. %s error = %%v, wantErr %%v\", tt.name, err, tt.wantErr)\n", fnName))
				}
				sb.WriteString(indent + "\tcontinue\n")
			} else {
				if hasInputs {
					sb.WriteString(fmt.Sprintf("t.Fatalf(\"%s(%s) error = %%v, wantErr %%v\", %s, err, tt.wantErr)\n", fn.Name, inputFmt, inputArgs))
				} else {
					sb.WriteString(fmt.Sprintf("t.Fatalf(\"%s error = %%v, wantErr %%v\", err, tt.wantErr)\n", fnName))
				}
			}
			sb.WriteString(indent + "}\n")

			// wantErr early return (only for subtests)
			if !noSubtests {
				sb.WriteString(indent)
				sb.WriteString("if tt.wantErr {\n")
				sb.WriteString(indent + "\treturn\n")
				sb.WriteString(indent + "}\n")
			} else {
				sb.WriteString(indent)
				sb.WriteString("if tt.wantErr {\n")
				sb.WriteString(indent + "\treturn\n")
				sb.WriteString(indent + "}\n")
			}

			// Assertions for each return value
			for i, ret := range fn.Returns {
				gotVar := gotVars[i]
				if isComplexType(ret.Type) {
					if useGoCmp {
						if noSubtests {
							if hasInputs {
								sb.WriteString(indent)
								sb.WriteString(fmt.Sprintf("if !cmp.Equal(tt.%s, %s) {\n", ret.Name, gotVar))
								sb.WriteString(indent + "\t")
								sb.WriteString(fmt.Sprintf("t.Errorf(\"%%q. %s(%s) = %%v, want %%v\\ndiff=%%s\", tt.name, %s, %s, tt.%s, cmp.Diff(tt.%s, %s))\n", fn.Name, inputFmt, inputArgs, gotVar, ret.Name, ret.Name, gotVar))
								sb.WriteString(indent + "}\n")
							} else {
								sb.WriteString(indent)
								sb.WriteString(fmt.Sprintf("if !cmp.Equal(tt.%s, %s) {\n", ret.Name, gotVar))
								sb.WriteString(indent + "\t")
								sb.WriteString(fmt.Sprintf("t.Errorf(\"%%q. %s = %%v, want %%v\\ndiff=%%s\", tt.name, %s, tt.%s, cmp.Diff(tt.%s, %s))\n", fnName, gotVar, ret.Name, ret.Name, gotVar))
								sb.WriteString(indent + "}\n")
							}
						} else {
							sb.WriteString(indent)
							sb.WriteString(fmt.Sprintf("if !cmp.Equal(tt.%s, %s) {\n", ret.Name, gotVar))
							sb.WriteString(indent + "\t")
							sb.WriteString(fmt.Sprintf("t.Errorf(\"%s = %%v, want %%v\\ndiff=%%s\", %s, tt.%s, cmp.Diff(tt.%s, %s))\n", fnName, gotVar, ret.Name, ret.Name, gotVar))
							sb.WriteString(indent + "}\n")
						}
					} else {
						// Use reflect.DeepEqual
						if noSubtests {
							if hasInputs {
								sb.WriteString(indent)
								sb.WriteString(fmt.Sprintf("if !reflect.DeepEqual(%s, tt.%s) {\n", gotVar, ret.Name))
								sb.WriteString(indent + "\t")
								sb.WriteString(fmt.Sprintf("t.Errorf(\"%%q. %s(%s) = %%v, want %%v\", tt.name, %s, %s, tt.%s)\n", fn.Name, inputFmt, inputArgs, gotVar, ret.Name))
								sb.WriteString(indent + "}\n")
							} else {
								sb.WriteString(indent)
								sb.WriteString(fmt.Sprintf("if !reflect.DeepEqual(%s, tt.%s) {\n", gotVar, ret.Name))
								sb.WriteString(indent + "\t")
								sb.WriteString(fmt.Sprintf("t.Errorf(\"%%q. %s = %%v, want %%v\", tt.name, %s, tt.%s)\n", fnName, gotVar, ret.Name))
								sb.WriteString(indent + "}\n")
							}
						} else {
							sb.WriteString(indent)
							sb.WriteString(fmt.Sprintf("if !reflect.DeepEqual(%s, tt.%s) {\n", gotVar, ret.Name))
							sb.WriteString(indent + "\t")
							sb.WriteString(fmt.Sprintf("t.Errorf(\"%s = %%v, want %%v\", %s, tt.%s)\n", fnName, gotVar, ret.Name))
							sb.WriteString(indent + "}\n")
						}
					}
				} else {
					// Simple comparison
					if noSubtests {
						if hasInputs {
							sb.WriteString(indent)
							if len(fn.Returns) == 1 && ret.Name == "want" {
								sb.WriteString(fmt.Sprintf("if %s != tt.%s {\n", gotVar, ret.Name))
								sb.WriteString(indent + "\t")
								sb.WriteString(fmt.Sprintf("t.Errorf(\"%%q. %s(%s) = %%v, want %%v\", tt.name, %s, %s, tt.%s)\n", fn.Name, inputFmt, inputArgs, gotVar, ret.Name))
								sb.WriteString(indent + "}\n")
							} else {
								sb.WriteString(fmt.Sprintf("if %s != tt.%s {\n", gotVar, ret.Name))
								sb.WriteString(indent + "\t")
								sb.WriteString(fmt.Sprintf("t.Errorf(\"%%q. %s(%s) = %%v, want %%v\", tt.name, %s, %s, tt.%s)\n", fn.Name, inputFmt, inputArgs, gotVar, ret.Name))
								sb.WriteString(indent + "}\n")
							}
						} else {
							sb.WriteString(indent)
							sb.WriteString(fmt.Sprintf("if %s != tt.%s {\n", gotVar, ret.Name))
							sb.WriteString(indent + "\t")
							if len(fn.Returns) == 1 && ret.Name == "want" {
								sb.WriteString(fmt.Sprintf("t.Errorf(\"%%q. %s = %%v, want %%v\", tt.name, %s, tt.%s)\n", fnName, gotVar, ret.Name))
							} else {
								// Multiple named returns
								sb.WriteString(fmt.Sprintf("t.Errorf(\"%%q. %s %s = %%v, want %%v\", tt.name, %s, tt.%s)\n", fnName, gotVar, gotVar, ret.Name))
							}
							sb.WriteString(indent + "}\n")
						}
					} else {
						// subtests version
						sb.WriteString(indent)
						if len(fn.Returns) == 1 && ret.Name == "want" {
							// Single non-error return
							sb.WriteString(fmt.Sprintf("if %s != tt.%s {\n", gotVar, ret.Name))
							sb.WriteString(indent + "\t")
							if hasInputs {
								sb.WriteString(fmt.Sprintf("t.Errorf(\"%s(%s) = %%v, want %%v\", %s, %s, tt.%s)\n", fn.Name, inputFmt, inputArgs, gotVar, ret.Name))
							} else {
								sb.WriteString(fmt.Sprintf("t.Errorf(\"%s = %%v, want %%v\", %s, tt.%s)\n", fnName, gotVar, ret.Name))
							}
							sb.WriteString(indent + "}\n")
						} else {
							// Multiple returns
							sb.WriteString(fmt.Sprintf("if %s != tt.%s {\n", gotVar, ret.Name))
							sb.WriteString(indent + "\t")
							if hasInputs {
								sb.WriteString(fmt.Sprintf("t.Errorf(\"%s(%s) %s = %%v, want %%v\", %s, %s, tt.%s)\n", fn.Name, inputFmt, gotVar, inputArgs, gotVar, ret.Name))
							} else {
								sb.WriteString(fmt.Sprintf("t.Errorf(\"%s %s = %%v, want %%v\", %s, tt.%s)\n", fnName, gotVar, gotVar, ret.Name))
							}
							sb.WriteString(indent + "}\n")
						}
					}
				}
			}
		}
		return
	}

	// No error return
	if !fn.HasResults() {
		// No returns - just call
		sb.WriteString(indent)
		sb.WriteString(callStr)
		sb.WriteString("\n")
		return
	}

	// Has returns but no error
	if useTestify {
		// assert.Equal(t, tt.want, got)
		if len(fn.Returns) == 1 {
			ret := fn.Returns[0]
			gotVar := gotVars[0]
			if noSubtests {
				sb.WriteString(indent)
				if hasInputs {
					sb.WriteString(fmt.Sprintf("assert.Equalf(t, tt.%s, %s, \"%%q. %s(%s)\", tt.name, %s)\n", ret.Name, callStr, fn.Name, inputFmt, inputArgs))
				} else {
					sb.WriteString(fmt.Sprintf("assert.Equalf(t, tt.%s, %s, \"%%q. %s()\", tt.name)\n", ret.Name, callStr, fn.Name))
				}
				_ = gotVar
			} else {
				sb.WriteString(indent)
				if hasInputs {
					sb.WriteString(fmt.Sprintf("assert.Equalf(t, tt.%s, %s, \"%s(%s)\", %s)\n", ret.Name, callStr, fn.Name+"()", inputFmt, inputArgs))
				} else {
					sb.WriteString(fmt.Sprintf("assert.Equal(t, tt.%s, %s)\n", ret.Name, callStr))
				}
			}
		}
		return
	}

	if len(fn.Returns) == 1 {
		ret := fn.Returns[0]
		gotVar := gotVars[0]

		if isComplexType(ret.Type) {
			if useGoCmp {
				if noSubtests {
					sb.WriteString(indent)
					if hasInputs {
						sb.WriteString(fmt.Sprintf("if got := %s; !cmp.Equal(tt.%s, got) {\n", callStr, ret.Name))
						sb.WriteString(indent + "\t")
						sb.WriteString(fmt.Sprintf("t.Errorf(\"%%q. %s(%s) = %%v, want %%v\\ndiff=%%s\", tt.name, %s, got, tt.%s, cmp.Diff(tt.%s, got))\n", fn.Name, inputFmt, inputArgs, ret.Name, ret.Name))
						sb.WriteString(indent + "}\n")
					} else {
						sb.WriteString(fmt.Sprintf("if got := %s; !cmp.Equal(tt.%s, got) {\n", callStr, ret.Name))
						sb.WriteString(indent + "\t")
						sb.WriteString(fmt.Sprintf("t.Errorf(\"%%q. %s = %%v, want %%v\\ndiff=%%s\", tt.name, got, tt.%s, cmp.Diff(tt.%s, got))\n", fnName, ret.Name, ret.Name))
						sb.WriteString(indent + "}\n")
					}
				} else {
					sb.WriteString(indent)
					sb.WriteString(fmt.Sprintf("if got := %s; !cmp.Equal(tt.%s, got) {\n", callStr, ret.Name))
					sb.WriteString(indent + "\t")
					sb.WriteString(fmt.Sprintf("t.Errorf(\"%s = %%v, want %%v\\ndiff=%%s\", got, tt.%s, cmp.Diff(tt.%s, got))\n", fnName, ret.Name, ret.Name))
					sb.WriteString(indent + "}\n")
				}
			} else {
				// reflect.DeepEqual
				if noSubtests {
					if hasInputs {
						sb.WriteString(indent)
						sb.WriteString(fmt.Sprintf("if got := %s; !reflect.DeepEqual(got, tt.%s) {\n", callStr, ret.Name))
						sb.WriteString(indent + "\t")
						sb.WriteString(fmt.Sprintf("t.Errorf(\"%%q. %s(%s) = %%v, want %%v\", tt.name, %s, got, tt.%s)\n", fn.Name, inputFmt, inputArgs, ret.Name))
						sb.WriteString(indent + "}\n")
					} else {
						sb.WriteString(indent)
						sb.WriteString(fmt.Sprintf("if got := %s; !reflect.DeepEqual(got, tt.%s) {\n", callStr, ret.Name))
						sb.WriteString(indent + "\t")
						sb.WriteString(fmt.Sprintf("t.Errorf(\"%%q. %s = %%v, want %%v\", tt.name, got, tt.%s)\n", fnName, ret.Name))
						sb.WriteString(indent + "}\n")
					}
				} else {
					sb.WriteString(indent)
					sb.WriteString(fmt.Sprintf("if got := %s; !reflect.DeepEqual(got, tt.%s) {\n", callStr, ret.Name))
					sb.WriteString(indent + "\t")
					sb.WriteString(fmt.Sprintf("t.Errorf(\"%s = %%v, want %%v\", got, tt.%s)\n", fnName, ret.Name))
					sb.WriteString(indent + "}\n")
				}
			}
		} else {
			// Simple comparison
			if noSubtests {
				if hasInputs {
					sb.WriteString(indent)
					sb.WriteString(fmt.Sprintf("if got := %s; got != tt.%s {\n", callStr, ret.Name))
					sb.WriteString(indent + "\t")
					sb.WriteString(fmt.Sprintf("t.Errorf(\"%%q. %s(%s) = %%v, want %%v\", tt.name, %s, got, tt.%s)\n", fn.Name, inputFmt, inputArgs, ret.Name))
					sb.WriteString(indent + "}\n")
				} else {
					sb.WriteString(indent)
					sb.WriteString(fmt.Sprintf("if got := %s; got != tt.%s {\n", callStr, ret.Name))
					sb.WriteString(indent + "\t")
					sb.WriteString(fmt.Sprintf("t.Errorf(\"%%q. %s = %%v, want %%v\", tt.name, got, tt.%s)\n", fnName, ret.Name))
					sb.WriteString(indent + "}\n")
				}
			} else {
				sb.WriteString(indent)
				sb.WriteString(fmt.Sprintf("if got := %s; got != tt.%s {\n", callStr, ret.Name))
				sb.WriteString(indent + "\t")
				if hasInputs {
					sb.WriteString(fmt.Sprintf("t.Errorf(\"%s(%s) = %%v, want %%v\", %s, got, tt.%s)\n", fn.Name, inputFmt, inputArgs, ret.Name))
				} else {
					sb.WriteString(fmt.Sprintf("t.Errorf(\"%s = %%v, want %%v\", got, tt.%s)\n", fnName, ret.Name))
				}
				sb.WriteString(indent + "}\n")
			}
		}
	} else {
		// Multiple returns
		// First get all values
		sb.WriteString(indent)
		allGotVars := strings.Join(gotVars, ", ")
		sb.WriteString(fmt.Sprintf("%s := %s\n", allGotVars, callStr))
		_ = gotVar

		for i, ret := range fn.Returns {
			gotVar := gotVars[i]
			if isComplexType(ret.Type) {
				if useGoCmp {
					if noSubtests {
						sb.WriteString(indent)
						sb.WriteString(fmt.Sprintf("if !cmp.Equal(tt.%s, %s) {\n", ret.Name, gotVar))
						sb.WriteString(indent + "\t")
						sb.WriteString(fmt.Sprintf("t.Errorf(\"%%q. %s %s = %%v, want %%v\\ndiff=%%s\", tt.name, %s, tt.%s, cmp.Diff(tt.%s, %s))\n", fnName, gotVar, gotVar, ret.Name, ret.Name, gotVar))
						sb.WriteString(indent + "}\n")
					} else {
						sb.WriteString(indent)
						sb.WriteString(fmt.Sprintf("if !cmp.Equal(tt.%s, %s) {\n", ret.Name, gotVar))
						sb.WriteString(indent + "\t")
						sb.WriteString(fmt.Sprintf("t.Errorf(\"%s %s = %%v, want %%v\\ndiff=%%s\", %s, tt.%s, cmp.Diff(tt.%s, %s))\n", fnName, gotVar, gotVar, ret.Name, ret.Name, gotVar))
						sb.WriteString(indent + "}\n")
					}
				} else {
					if noSubtests {
						sb.WriteString(indent)
						sb.WriteString(fmt.Sprintf("if !reflect.DeepEqual(%s, tt.%s) {\n", gotVar, ret.Name))
						sb.WriteString(indent + "\t")
						sb.WriteString(fmt.Sprintf("t.Errorf(\"%%q. %s %s = %%v, want %%v\", tt.name, %s, tt.%s)\n", fnName, gotVar, gotVar, ret.Name))
						sb.WriteString(indent + "}\n")
					} else {
						sb.WriteString(indent)
						sb.WriteString(fmt.Sprintf("if !reflect.DeepEqual(%s, tt.%s) {\n", gotVar, ret.Name))
						sb.WriteString(indent + "\t")
						sb.WriteString(fmt.Sprintf("t.Errorf(\"%s %s = %%v, want %%v\", %s, tt.%s)\n", fnName, gotVar, gotVar, ret.Name))
						sb.WriteString(indent + "}\n")
					}
				}
			} else {
				if noSubtests {
					sb.WriteString(indent)
					sb.WriteString(fmt.Sprintf("if %s != tt.%s {\n", gotVar, ret.Name))
					sb.WriteString(indent + "\t")
					sb.WriteString(fmt.Sprintf("t.Errorf(\"%%q. %s %s = %%v, want %%v\", tt.name, %s, tt.%s)\n", fnName, gotVar, gotVar, ret.Name))
					sb.WriteString(indent + "}\n")
				} else {
					sb.WriteString(indent)
					sb.WriteString(fmt.Sprintf("if %s != tt.%s {\n", gotVar, ret.Name))
					sb.WriteString(indent + "\t")
					sb.WriteString(fmt.Sprintf("t.Errorf(\"%s %s = %%v, want %%v\", %s, tt.%s)\n", fnName, gotVar, gotVar, ret.Name))
					sb.WriteString(indent + "}\n")
				}
			}
		}
	}
}
