						sb.WriteString(fmt.Sprintf("if !cmp.Equal(tt.%s, %s) {\n", ret.Name, gotVar))
						sb.WriteString(indent + "\t")
						sb.WriteString(fmt.Sprintf("t.Errorf(\"%s %s = %%v, want %%v\\ndiff=%%s\", %s, tt.%s, cmp.Diff(tt.%s, %s))\n", fnName, gotVar, gotVar, ret.Name, ret.Name, gotVar))
						sb.WriteString(indent + "}\n")
					}
				} else {
					if noSubtests {
						sb.WriteString(indent)
						sb.WriteString(fmt.Sprintf("if !reflect.DeepEqual(%s, tt.%s) {\n", gotVar, ret.Name))
						sb.WriteString(indent + "\t")
						sb.WriteString(fmt.Sprintf("t.Errorf(\"%%q. %s %s = %%v, want %%v\", tt.name, %s, tt.%s)\n", fnName, gotVar, gotVar, ret.Name))
						sb.WriteString(indent + "}\n")
