package gotests

import (
	"fmt"
	"go/ast"
	"go/parser"
	"go/token"
	"os"
	"path/filepath"
	"regexp"
	"strings"

	"gotests/internal/input"
	"gotests/internal/output"
	"gotests/internal/render"
)

// Options controls test generation behavior
type Options struct {
	Only               string
	Excl               string
	Exported           bool
	PrintInputs        bool
	Named              bool
	Parallel           bool
	Subtests           bool
	WriteFiles         bool
	Template           string
	TemplateDir        string
	TemplateParamsFile string
	UseGoCmp           bool
}

// Run processes the given path (file or directory) and generates tests
func Run(path string, opts *Options) error {
	// Handle recursive pattern
	if strings.HasSuffix(path, "...") {
		base := strings.TrimSuffix(path, "...")
		base = strings.TrimRight(base, "/")
		if base == "" || base == "." {
			base = "."
		}
		return runRecursive(base, opts)
	}

	info, err := os.Stat(path)
	if err != nil {
		return fmt.Errorf("input.Files: os.Stat: %w", err)
	}

	if info.IsDir() {
		return runDir(path, opts)
	}
	return runFile(path, opts)
}

func runRecursive(base string, opts *Options) error {
	return filepath.Walk(base, func(path string, info os.FileInfo, err error) error {
		if err != nil {
			return err
		}
		if !info.IsDir() {
			return nil
		}
		// Skip hidden directories
		if path != base && strings.HasPrefix(filepath.Base(path), ".") {
			return filepath.SkipDir
		}
		return runDir(path, opts)
	})
}

func runDir(dir string, opts *Options) error {
	// Find all .go files (non-test) in the directory
	fset := token.NewFileSet()
	pkgs, err := parser.ParseDir(fset, dir, func(fi os.FileInfo) bool {
		name := fi.Name()
		return !strings.HasSuffix(name, "_test.go")
	}, 0)
	if err != nil {
		return fmt.Errorf("Parser.Parse source file: target parser.ParseFile(): %w", err)
	}

	// Find all existing test files (scan all test files in dir)
	existingTests := findExistingTests(dir)

