		return false
	}
	if exportedOnly {
		if len(funcName) == 0 {
			return false
		}
		c := funcName[0]
		return c >= 'A' && c <= 'Z'
	}
	if onlyRe != nil {
		return onlyRe.MatchString(funcName)
	}
	return true // -all
}

func processFile(filename string, fset *token.FileSet, file *ast.File, pkgName string, existingTests map[string]bool, opts *Options) error {
	var onlyRe, exclRe *regexp.Regexp
	var err error
	if opts.Only != "" {
		onlyRe, err = regexp.Compile(opts.Only)
		if err != nil {
			return fmt.Errorf("invalid -only regexp: %w", err)
		}
	}
	if opts.Excl != "" {
		exclRe, err = regexp.Compile(opts.Excl)
		if err != nil {
			return fmt.Errorf("invalid -excl regexp: %w", err)
		}
	}

	// Collect functions/methods to test
	funcs := input.CollectFunctions(fset, file, func(name string) bool {
		return matchFilter(name, onlyRe, exclRe, opts.Exported)
	})

	// Filter out existing tests
	var newFuncs []*input.Function
	for _, fn := range funcs {
		testName := fn.TestName()
		if !existingTests[testName] {
			newFuncs = append(newFuncs, fn)
		}
	}

	if len(newFuncs) == 0 {
		fmt.Printf("No tests generated for %s\n", filename)
		return nil
	}

	// Compute test filename
	testFile := testFilename(filename)

	// Parse existing test file if it exists
	var existingTestFile *ast.File
	var existingFset = token.NewFileSet()
	if _, statErr := os.Stat(testFile); statErr == nil {
		var parseErr error
		existingTestFile, parseErr = parser.ParseFile(existingFset, testFile, nil, parser.ParseComments)
		if parseErr != nil {
			// If we can't parse existing test file, ignore it
			existingTestFile = nil
			existingFset = token.NewFileSet()
		}
	}

	renderOpts := &render.Options{
		PrintInputs:        opts.PrintInputs,
		Named:              opts.Named,
		Parallel:           opts.Parallel,
		Subtests:           opts.Subtests,
		Template:           opts.Template,
		TemplateDir:        opts.TemplateDir,
		TemplateParamsFile: opts.TemplateParamsFile,
		UseGoCmp:           opts.UseGoCmp,
	}

	// Print generated names
	for _, fn := range newFuncs {
		fmt.Printf("Generated %s\n", fn.TestName())
	}

	generated, err := render.GenerateTests(pkgName, newFuncs, existingTestFile, existingFset, renderOpts)
	if err != nil {
		return fmt.Errorf("render: %w", err)
	}

	if opts.WriteFiles {
		return output.WriteFile(testFile, generated)
	}
	fmt.Print(string(generated))
	return nil
}

func testFilename(goFile string) string {
	base := filepath.Base(goFile)
	ext := filepath.Ext(base)
	name := base[:len(base)-len(ext)]
	return filepath.Join(filepath.Dir(goFile), name+"_test.go")
}
