cat > /workspace/gotests/internal/render/render.go << 'GOEOF'
package render

import (
	"bytes"
	"fmt"
	"go/ast"
	"go/format"
	"go/printer"
	"go/token"
	"strings"

	"gotests/internal/input"
)

// Options for rendering
type Options struct {
	PrintInputs        bool
	Named              bool
	Parallel           bool
	Subtests           bool
	Template           string
	TemplateDir        string
	TemplateParamsFile string
	UseGoCmp           bool
}

// GenerateTests generates test code for the given functions
func GenerateTests(pkgName string, funcs []*input.Function, existingFile *ast.File, existingFset *token.FileSet, opts *Options) ([]byte, error) {
	useTestify := opts.Template == "testify"
	useGoCmp := opts.UseGoCmp

	// Determine needed imports
	needReflect := false
	if !useGoCmp && !useTestify {
		for _, fn := range funcs {
			if needsReflectDeepEqual(fn) {
				needReflect = true
				break
			}
		}
	}

	// Check existing file for reflect import
	if existingFile != nil && !useGoCmp && !useTestify {
		for _, imp := range existingFile.Imports {
			if imp.Path.Value == `"reflect"` {
				needReflect = true
				break
			}
		}
	}

	needFmt := false
	if useTestify && !opts.Subtests {
		for _, fn := range funcs {
			if fn.ReturnsErr {
				needFmt = true
				break
			}
		}
	}
	// Check existing file
	if existingFile != nil && useTestify && !opts.Subtests {
		for _, imp := range existingFile.Imports {
			if imp.Path.Value == `"fmt"` {
				needFmt = true
				break
			}
		}
	}

	var buf bytes.Buffer

	// Package declaration
	buf.WriteString("package ")
	buf.WriteString(pkgName)
	buf.WriteString("\n\n")

	// Build imports
	importSet := make(map[string]bool)
	var importOrder []string

	addImport := func(path string) {
		if !importSet[path] {
			importSet[path] = true
			importOrder = append(importOrder, path)
		}
	}

	// Existing imports first
	if existingFile != nil {
		for _, imp := range existingFile.Imports {
			path := imp.Path.Value
			if imp.Name != nil {
				path = imp.Name.Name + " " + path
			}
			addImport(path)
		}
	}

	// New imports
	if needFmt {
		addImport(`"fmt"`)
	}
	addImport(`"testing"`)
	if needReflect {
		addImport(`"reflect"`)
	}
	if useGoCmp {
		addImport(`"github.com/google/go-cmp/cmp"`)
	}
	if useTestify {
		addImport(`"github.com/stretchr/testify/assert"`)
	}

	// Write imports
	if len(importOrder) == 1 {
		buf.WriteString("import ")
		buf.WriteString(importOrder[0])
		buf.WriteString("\n")
	} else if len(importOrder) > 1 {
		buf.WriteString("import (\n")
		for _, imp := range importOrder {
			buf.WriteString("\t")
			buf.WriteString(imp)
			buf.WriteString("\n")
		}
		buf.WriteString(")\n")
	}

	// Existing test functions
	if existingFile != nil {
		for _, decl := range existingFile.Decls {
			fn, ok := decl.(*ast.FuncDecl)
			if !ok {
				continue
			}
			buf.WriteString("\n")
			if err := printer.Fprint(&buf, existingFset, fn); err != nil {
				return nil, fmt.Errorf("print existing function: %w", err)
			}
			buf.WriteString("\n")
		}
	}

	// New test functions
	for _, fn := range funcs {
		buf.WriteString("\n")
		buf.WriteString(renderTestFunc(fn, opts, needReflect, useGoCmp, useTestify))
		buf.WriteString("\n")
	}

	// Format with gofmt
	formatted, err := format.Source(buf.Bytes())
	if err != nil {
		// Return unformatted - caller handles error
		return buf.Bytes(), nil
	}
	return formatted, nil
}

func needsReflectDeepEqual(fn *input.Function) bool {
	for _, ret := range fn.Returns {
		if isComplexType(ret.Type) {
			return true
		}
	}
	return false
}

func isComplexType(t string) bool {
	switch t {
	case "bool", "string", "error",
		"int", "int8", "int16", "int32", "int64",
		"uint", "uint8", "uint16", "uint32", "uint64",
		"uintptr", "float32", "float64",
		"complex64", "complex128",
		"byte", "rune":
		return false
	}
	return true
}

// returnVarName maps a "want" name to a "got" name
func returnVarName(wantName string) string {
	if wantName == "want" {
		return "got"
	}
	if strings.HasPrefix(wantName, "want") {
		return "got" + wantName[4:]
	}
	return "got"
}

// funcDisplayName returns the function name for error messages: "FuncName()" or "Type.FuncName()"
func funcDisplayName(fn *input.Function) string {
	if fn.Receiver != nil {
		return fn.Receiver.Type + "." + fn.Name + "()"
	}
	return fn.Name + "()"
}

// callExpr returns the function call expression (without assignment)
func callExpr(fn *input.Function, recvVar string) string {
	var sb strings.Builder
	if fn.Receiver != nil {
		sb.WriteString(recvVar)
		sb.WriteString(".")
		sb.WriteString(fn.Name)
	} else {
		sb.WriteString(fn.Name)
		if len(fn.TypeParams) > 0 {
			sb.WriteString("[")
			sb.WriteString(strings.Join(fn.TypeParams, ", "))
			sb.WriteString("]")
		}
	}
	sb.WriteString("(")
	for i, p := range fn.Params {
		if i > 0 {
			sb.WriteString(", ")
		}
		sb.WriteString("tt.args.")
		sb.WriteString(p.Name)
		if p.IsVariadic {
			sb.WriteString("...")
		}
	}
	sb.WriteString(")")
	return sb.String()
}

// argsFormatStr returns format string for -i flag: "%v, %v"
func argsFormatStr(fn *input.Function) string {
	parts := make([]string, len(fn.Params))
	for i := range parts {
		parts[i] = "%v"
	}
	return strings.Join(parts, ", ")
}

// argsVarStr returns variable list for -i flag: "tt.args.a, tt.args.b"
func argsVarStr(fn *input.Function) string {
	parts := make([]string, len(fn.Params))
	for i, p := range fn.Params {
		parts[i] = "tt.args." + p.Name
	}
	return strings.Join(parts, ", ")
}

// renderTestFunc generates the complete test function
func renderTestFunc(fn *input.Function, opts *Options, needReflect, useGoCmp, useTestify bool) string {
	var sb strings.Builder

	recvVar := ""
	if fn.Receiver != nil {
		recvVar = fn.Receiver.Name
	}

	sb.WriteString("func ")
	sb.WriteString(fn.TestName())
	sb.WriteString("(t *testing.T) {\n")

	if opts.Parallel {
		sb.WriteString("\tt.Parallel()\n")
	}

	// Fields struct
	if fn.ReceiverHasFields() {
		sb.WriteString("\ttype fields struct {\n")
		for _, f := range fn.Receiver.Fields {
			sb.WriteString(fmt.Sprintf("\t\t%s %s\n", f.Name, f.Type))
		}
		sb.WriteString("\t}\n")
	}

	// Args struct
	if fn.HasArgs() {
		sb.WriteString("\ttype args struct {\n")
		for _, p := range fn.Params {
			sb.WriteString(fmt.Sprintf("\t\t%s %s\n", p.Name, p.Type))
		}
		sb.WriteString("\t}\n")
	}

	// Test cases struct
	renderTestCasesStruct(&sb, fn, opts, recvVar, useTestify)

	// Loop header
	if opts.Named {
		sb.WriteString("\tfor name, tt := range tests {\n")
	} else {
		sb.WriteString("\tfor _, tt := range tests {\n")
	}

	if opts.Subtests {
		// With subtests
		if opts.Named {
			sb.WriteString("\t\tt.Run(name, func(t *testing.T) {\n")
		} else {
			sb.WriteString("\t\tt.Run(tt.name, func(t *testing.T) {\n")
		}
		if opts.Parallel {
			sb.WriteString("\t\t\tt.Parallel()\n")
		}
		renderReceiverSetup(&sb, fn, recvVar, "\t\t\t")
		renderBody(&sb, fn, opts, recvVar, useGoCmp, useTestify, needReflect, "\t\t\t", false)
		sb.WriteString("\t\t})\n")
	} else {
		renderReceiverSetup(&sb, fn, recvVar, "\t\t")
		renderBody(&sb, fn, opts, recvVar, useGoCmp, useTestify, needReflect, "\t\t", true)
	}

	sb.WriteString("\t}\n")
	sb.WriteString("}")
	return sb.String()
}

func renderTestCasesStruct(sb *strings.Builder, fn *input.Function, opts *Options, recvVar string, useTestify bool) {
	if opts.Named {
		sb.WriteString("\ttests := map[string]struct {\n")
	} else {
		sb.WriteString("\ttests := []struct {\n")
		sb.WriteString("\t\tname string\n")
	}

	// Receiver field (no-fields case)
	if fn.Receiver != nil && !fn.ReceiverHasFields() {
		typeStr := fn.Receiver.Type
		if len(fn.TypeParams) > 0 {
			typeStr += "[" + strings.Join(fn.TypeParams, ", ") + "]"
		}
		ptrStr := ""
		if fn.Receiver.IsPtr {
			ptrStr = "*"
		}
		sb.WriteString(fmt.Sprintf("\t\t%s %s%s\n", recvVar, ptrStr, typeStr))
	}

	// Fields field
	if fn.ReceiverHasFields() {
		sb.WriteString("\t\tfields fields\n")
	}

	// Args field
	if fn.HasArgs() {
		sb.WriteString("\t\targs args\n")
	}

	// Return values
	if fn.OnlyError {
		if useTestify {
			sb.WriteString("\t\tassertion assert.ErrorAssertionFunc\n")
		} else {
			sb.WriteString("\t\twantErr bool\n")
		}
	} else if fn.ReturnsErr {
		for _, ret := range fn.Returns {
			sb.WriteString(fmt.Sprintf("\t\t%s %s\n", ret.Name, ret.Type))
		}
		if useTestify {
			sb.WriteString("\t\tassertion assert.ErrorAssertionFunc\n")
		} else {
			sb.WriteString("\t\twantErr bool\n")
		}
	} else {
		for _, ret := range fn.Returns {
			sb.WriteString(fmt.Sprintf("\t\t%s %s\n", ret.Name, ret.Type))
		}
	}

	sb.WriteString("\t}{\n")
	sb.WriteString("\t\t// TODO: Add test cases.\n")
	sb.WriteString("\t}\n")
}

func renderReceiverSetup(sb *strings.Builder, fn *input.Function, recvVar, indent string) {
	if fn.Receiver == nil {
		return
	}

	typeName := fn.Receiver.Type
	typeParamStr := ""
	if len(fn.TypeParams) > 0 {
		typeParamStr = "[" + strings.Join(fn.TypeParams, ", ") + "]"
	}

	ptrStr := ""
	if fn.Receiver.IsPtr {
		ptrStr = "&"
	}

	if fn.ReceiverHasFields() {
		sb.WriteString(fmt.Sprintf("%s%s := %s%s%s{\n", indent, recvVar, ptrStr, typeName, typeParamStr))
		for _, f := range fn.Receiver.Fields {
			sb.WriteString(fmt.Sprintf("%s\t%s: tt.fields.%s,\n", indent, f.Name, f.Name))
		}
		sb.WriteString(fmt.Sprintf("%s}\n", indent))
	} else {
		sb.WriteString(fmt.Sprintf("%s%s := %s%s%s{}\n", indent, recvVar, ptrStr, typeName, typeParamStr))
	}
}

func renderBody(sb *strings.Builder, fn *input.Function, opts *Options, recvVar string, useGoCmp, useTestify, needReflect bool, indent string, noSubtests bool) {
	call := callExpr(fn, recvVar)
	fnDisplay := funcDisplayName(fn)
	hasInputs := opts.PrintInputs && len(fn.Params) > 0
	argsFmt := argsFormatStr(fn)
	argsVars := argsVarStr(fn)

	if fn.OnlyError {
		renderOnlyError(sb, fn, call, fnDisplay, indent, noSubtests, hasInputs, argsFmt, argsVars, useTestify)
		return
	}

	if !fn.HasResults() && !fn.ReturnsErr {
		// No returns
		sb.WriteString(fmt.Sprintf("%s%s\n", indent, call))
		return
	}

	if fn.ReturnsErr {
		renderWithError(sb, fn, call, fnDisplay, indent, noSubtests, hasInputs, argsFmt, argsVars, useGoCmp, useTestify, needReflect)
		return
	}

	// No error, has returns
	renderNoError(sb, fn, call, fnDisplay, indent, noSubtests, hasInputs, argsFmt, argsVars, useGoCmp, useTestify, needReflect)
}

func renderOnlyError(sb *strings.Builder, fn *input.Function, call, fnDisplay, indent string, noSubtests, hasInputs bool, argsFmt, argsVars string, useTestify bool) {
	if useTestify {
		if noSubtests {
			if hasInputs {
				sb.WriteString(fmt.Sprintf("%stt.assertion(t, %s, fmt.Sprintf(\"%%q. %s(%s)\", tt.name, %s))\n",
					indent, call, fn.Name+"()", argsFmt, argsVars))
			} else {
				sb.WriteString(fmt.Sprintf("%stt.assertion(t, %s, fmt.Sprintf(\"%%q. %s\", tt.name))\n",
					indent, call, fn.Name+"()"))
			}
		} else {
			if hasInputs {
				sb.WriteString(fmt.Sprintf("%stt.assertion(t, %s, fmt.Sprintf(\"%s(%s)\", %s))\n",
					indent, call, fn.Name+"()", argsFmt, argsVars))
			} else {
				sb.WriteString(fmt.Sprintf("%stt.assertion(t, %s)\n", indent, call))
			}
		}
		return
	}

	if noSubtests {
		if hasInputs {
			sb.WriteString(fmt.Sprintf("%sif err := %s; (err != nil) != tt.wantErr {\n", indent, call))
			sb.WriteString(fmt.Sprintf("%s\tt.Errorf(\"%%q. %s(%s) error = %%v, wantErr %%v\", tt.name, %s, err, tt.wantErr)\n",
				indent, fn.Name, argsFmt, argsVars))
			sb.WriteString(fmt.Sprintf("%s}\n", indent))
		} else {
			sb.WriteString(fmt.Sprintf("%sif err := %s; (err != nil) != tt.wantErr {\n", indent, call))
			sb.WriteString(fmt.Sprintf("%s\tt.Errorf(\"%%q. %s error = %%v, wantErr %%v\", tt.name, err, tt.wantErr)\n",
				indent, fnDisplay))
			sb.WriteString(fmt.Sprintf("%s}\n", indent))
		}
	} else {
		if hasInputs {
			sb.WriteString(fmt.Sprintf("%sif err := %s; (err != nil) != tt.wantErr {\n", indent, call))
			sb.WriteString(fmt.Sprintf("%s\tt.Errorf(\"%s(%s) error = %%v, wantErr %%v\", %s, err, tt.wantErr)\n",
				indent, fn.Name, argsFmt, argsVars))
			sb.WriteString(fmt.Sprintf("%s}\n", indent))
		} else {
			sb.WriteString(fmt.Sprintf("%sif err := %s; (err != nil) != tt.wantErr {\n", indent, call))
			sb.WriteString(fmt.Sprintf("%s\tt.Errorf(\"%s error = %%v, wantErr %%v\", err, tt.wantErr)\n",
				indent, fnDisplay))
			sb.WriteString(fmt.Sprintf("%s}\n", indent))
		}
	}
}

func renderWithError(sb *strings.Builder, fn *input.Function, call, fnDisplay, indent string, noSubtests, hasInputs bool, argsFmt, argsVars string, useGoCmp, useTestify, needReflect bool) {
	// Build got vars
	gotVars := make([]string, len(fn.Returns))
	for i, ret := range fn.Returns {
		gotVars[i] = returnVarName(ret.Name)
	}

	allVars := append(append([]string{}, gotVars...), "err")
	assignment := strings.Join(allVars, ", ")

	if useTestify {
		sb.WriteString(fmt.Sprintf("%s%s := %s\n", indent, assignment, call))

		if noSubtests {
			if hasInputs {
				sb.WriteString(fmt.Sprintf("%stt.assertion(t, err, fmt.Sprintf(\"%%q. %s(%s)\", tt.name, %s))\n",
					indent, fn.Name+"()", argsFmt, argsVars))
			} else {
				sb.WriteString(fmt.Sprintf("%stt.assertion(t, err, fmt.Sprintf(\"%%q. %s\", tt.name))\n",
					indent, fn.Name+"()"))
			}
		} else {
			if hasInputs {
				sb.WriteString(fmt.Sprintf("%stt.assertion(t, err, fmt.Sprintf(\"%s(%s)\", %s))\n",
					indent, fn.Name+"()", argsFmt, argsVars))
			} else {
				sb.WriteString(fmt.Sprintf("%stt.assertion(t, err)\n", indent))
			}
		}

		for i, ret := range fn.Returns {
			gotVar := gotVars[i]
			if noSubtests {
				sb.WriteString(fmt.Sprintf("%sassert.Equalf(t, tt.%s, %s, \"%%q. %s\", tt.name)\n",
					indent, ret.Name, gotVar, fn.Name+"()"))
			} else {
				if hasInputs {
					sb.WriteString(fmt.Sprintf("%sassert.Equalf(t, tt.%s, %s, \"%s(%s)\", %s)\n",
						indent, ret.Name, gotVar, fn.Name+"()", argsFmt, argsVars))
				} else {
					sb.WriteString(fmt.Sprintf("%sassert.Equal(t, tt.%s, %s)\n",
						indent, ret.Name, gotVar))
				}
			}
		}
		return
	}

	// Standard
	sb.WriteString(fmt.Sprintf("%s%s := %s\n", indent, assignment, call))

	// Error check
	if noSubtests {
		if hasInputs {
			sb.WriteString(fmt.Sprintf("%sif (err != nil) != tt.wantErr {\n", indent))
			sb.WriteString(fmt.Sprintf("%s\tt.Errorf(\"%%q. %s(%s) error = %%v, wantErr %%v\", tt.name, %s, err, tt.wantErr)\n",
				indent, fn.Name, argsFmt, argsVars))
			sb.WriteString(fmt.Sprintf("%s\tcontinue\n", indent))
			sb.WriteString(fmt.Sprintf("%s}\n", indent))
		} else {
			sb.WriteString(fmt.Sprintf("%sif (err != nil) != tt.wantErr {\n", indent))
			sb.WriteString(fmt.Sprintf("%s\tt.Errorf(\"%%q. %s error = %%v, wantErr %%v\", tt.name, err, tt.wantErr)\n",
				indent, fnDisplay))
			sb.WriteString(fmt.Sprintf("%s\tcontinue\n", indent))
			sb.WriteString(fmt.Sprintf("%s}\n", indent))
		}
		sb.WriteString(fmt.Sprintf("%sif tt.wantErr {\n", indent))
		sb.WriteString(fmt.Sprintf("%s\treturn\n", indent))
		sb.WriteString(fmt.Sprintf("%s}\n", indent))
	} else {
		if hasInputs {
			sb.WriteString(fmt.Sprintf("%sif (err != nil) != tt.wantErr {\n", indent))
			sb.WriteString(fmt.Sprintf("%s\tt.Fatalf(\"%s(%s) error = %%v, wantErr %%v\", %s, err, tt.wantErr)\n",
				indent, fn.Name, argsFmt, argsVars))
			sb.WriteString(fmt.Sprintf("%s}\n", indent))
		} else {
			sb.WriteString(fmt.Sprintf("%sif (err != nil) != tt.wantErr {\n", indent))
			sb.WriteString(fmt.Sprintf("%s\tt.Fatalf(\"%s error = %%v, wantErr %%v\", err, tt.wantErr)\n",
				indent, fnDisplay))
			sb.WriteString(fmt.Sprintf("%s}\n", indent))
		}
		sb.WriteString(fmt.Sprintf("%sif tt.wantErr {\n", indent))
		sb.WriteString(fmt.Sprintf("%s\treturn\n", indent))
		sb.WriteString(fmt.Sprintf("%s}\n", indent))
	}

	// Assertions for each return
	isMultiReturn := len(fn.Returns) > 1
	for i, ret := range fn.Returns {
		gotVar := gotVars[i]
		renderAssert(sb, fn, ret, gotVar, fnDisplay, indent, noSubtests, hasInputs, argsFmt, argsVars, useGoCmp, isMultiReturn)
	}
}

func renderNoError(sb *strings.Builder, fn *input.Function, call, fnDisplay, indent string, noSubtests, hasInputs bool, argsFmt, argsVars string, useGoCmp, useTestify, needReflect bool) {
	if len(fn.Returns) == 0 {
		sb.WriteString(fmt.Sprintf("%s%s\n", indent, call))
		return
	}

	if useTestify {
		ret := fn.Returns[0]
		if noSubtests {
			if hasInputs {
				sb.WriteString(fmt.Sprintf("%sassert.Equalf(t, tt.%s, %s, \"%%q. %s(%s)\", tt.name, %s)\n",
					indent, ret.Name, call, fn.Name+"()", argsFmt, argsVars))
			} else {
				sb.WriteString(fmt.Sprintf("%sassert.Equalf(t, tt.%s, %s, \"%%q. %s\", tt.name)\n",
					indent, ret.Name, call, fn.Name+"()"))
			}
		} else {
			if hasInputs {
				sb.WriteString(fmt.Sprintf("%sassert.Equalf(t, tt.%s, %s, \"%s(%s)\", %s)\n",
					indent, ret.Name, call, fn.Name+"()", argsFmt, argsVars))
			} else {
				sb.WriteString(fmt.Sprintf("%sassert.Equal(t, tt.%s, %s)\n",
					indent, ret.Name, call))
			}
		}
		return
	}

	if len(fn.Returns) == 1 {
		ret := fn.Returns[0]
		gotVar := returnVarName(ret.Name)
		isComplex := isComplexType(ret.Type)

		if isComplex {
			if useGoCmp {
				if noSubtests {
					if hasInputs {
						sb.WriteString(fmt.Sprintf("%sif got := %s; !cmp.Equal(tt.%s, got) {\n", indent, call, ret.Name))
						sb.WriteString(fmt.Sprintf("%s\tt.Errorf(\"%%q. %s(%s) = %%v, want %%v\\ndiff=%%s\", tt.name, %s, got, tt.%s, cmp.Diff(tt.%s, got))\n",
							indent, fn.Name, argsFmt, argsVars, ret.Name, ret.Name))
						sb.WriteString(fmt.Sprintf("%s}\n", indent))
					} else {
						sb.WriteString(fmt.Sprintf("%sif got := %s; !cmp.Equal(tt.%s, got) {\n", indent, call, ret.Name))
						sb.WriteString(fmt.Sprintf("%s\tt.Errorf(\"%%q. %s = %%v, want %%v\\ndiff=%%s\", tt.name, got, tt.%s, cmp.Diff(tt.%s, got))\n",
							indent, fnDisplay, ret.Name, ret.Name))
						sb.WriteString(fmt.Sprintf("%s}\n", indent))
					}
				} else {
					if hasInputs {
						sb.WriteString(fmt.Sprintf("%sif got := %s; !cmp.Equal(tt.%s, got) {\n", indent, call, ret.Name))
						sb.WriteString(fmt.Sprintf("%s\tt.Errorf(\"%s(%s) = %%v, want %%v\\ndiff=%%s\", %s, got, tt.%s, cmp.Diff(tt.%s, got))\n",
							indent, fn.Name, argsFmt, argsVars, ret.Name, ret.Name))
						sb.WriteString(fmt.Sprintf("%s}\n", indent))
					} else {
						sb.WriteString(fmt.Sprintf("%sif got := %s; !cmp.Equal(tt.%s, got) {\n", indent, call, ret.Name))
						sb.WriteString(fmt.Sprintf("%s\tt.Errorf(\"%s = %%v, want %%v\\ndiff=%%s\", got, tt.%s, cmp.Diff(tt.%s, got))\n",
							indent, fnDisplay, ret.Name, ret.Name))
						sb.WriteString(fmt.Sprintf("%s}\n", indent))
					}
				}
			} else {
				// reflect.DeepEqual
				if noSubtests {
					if hasInputs {
						sb.WriteString(fmt.Sprintf("%sif got := %s; !reflect.DeepEqual(got, tt.%s) {\n", indent, call, ret.Name))
						sb.WriteString(fmt.Sprintf("%s\tt.Errorf(\"%%q. %s(%s) = %%v, want %%v\", tt.name, %s, got, tt.%s)\n",
							indent, fn.Name, argsFmt, argsVars, ret.Name))
						sb.WriteString(fmt.Sprintf("%s}\n", indent))
					} else {
						sb.WriteString(fmt.Sprintf("%sif got := %s; !reflect.DeepEqual(got, tt.%s) {\n", indent, call, ret.Name))
						sb.WriteString(fmt.Sprintf("%s\tt.Errorf(\"%%q. %s = %%v, want %%v\", tt.name, got, tt.%s)\n",
							indent, fnDisplay, ret.Name))
						sb.WriteString(fmt.Sprintf("%s}\n", indent))
					}
				} else {
					if hasInputs {
						sb.WriteString(fmt.Sprintf("%sif got := %s; !reflect.DeepEqual(got, tt.%s) {\n", indent, call, ret.Name))
						sb.WriteString(fmt.Sprintf("%s\tt.Errorf(\"%s(%s) = %%v, want %%v\", %s, got, tt.%s)\n",
							indent, fn.Name, argsFmt, argsVars, ret.Name))
						sb.WriteString(fmt.Sprintf("%s}\n", indent))
					} else {
						sb.WriteString(fmt.Sprintf("%sif got := %s; !reflect.DeepEqual(got, tt.%s) {\n", indent, call, ret.Name))
						sb.WriteString(fmt.Sprintf("%s\tt.Errorf(\"%s = %%v, want %%v\", got, tt.%s)\n",
							indent, fnDisplay, ret.Name))
						sb.WriteString(fmt.Sprintf("%s}\n", indent))
					}
				}
			}
		} else {
			// Simple comparison
			if noSubtests {
				if hasInputs {
					sb.WriteString(fmt.Sprintf("%sif got := %s; got != tt.%s {\n", indent, call, ret.Name))
					sb.WriteString(fmt.Sprintf("%s\tt.Errorf(\"%%q. %s(%s) = %%v, want %%v\", tt.name, %s, got, tt.%s)\n",
						indent, fn.Name, argsFmt, argsVars, ret.Name))
					sb.WriteString(fmt.Sprintf("%s}\n", indent))
				} else {
					sb.WriteString(fmt.Sprintf("%sif got := %s; got != tt.%s {\n", indent, call, ret.Name))
					sb.WriteString(fmt.Sprintf("%s\tt.Errorf(\"%%q. %s = %%v, want %%v\", tt.name, got, tt.%s)\n",
						indent, fnDisplay, ret.Name))
					sb.WriteString(fmt.Sprintf("%s}\n", indent))
