		f := parseFunction(fn, typeMap, typeParamMap)
		funcs = append(funcs, f)
	}
	return funcs
}

type structInfo struct {
	fields []*Field
}

type typeParamInfo struct {
	constraints []string // per type param, in order
	names       []string // type param names
}

func buildTypeMap(file *ast.File) map[string]*structInfo {
	m := make(map[string]*structInfo)
	for _, decl := range file.Decls {
		gd, ok := decl.(*ast.GenDecl)
		if !ok {
			continue
		}
		for _, spec := range gd.Specs {
			ts, ok := spec.(*ast.TypeSpec)
			if !ok {
				continue
			}
			st, ok := ts.Type.(*ast.StructType)
			if !ok {
				continue
			}
			si := &structInfo{}
			if st.Fields != nil {
				for _, field := range st.Fields.List {
					typeStr := TypeExprToString(field.Type)
					if len(field.Names) == 0 {
						name := typeStr
						if idx := strings.LastIndex(name, "."); idx >= 0 {
							name = name[idx+1:]
						}
						name = strings.TrimPrefix(name, "*")
						si.fields = append(si.fields, &Field{Name: name, Type: typeStr})
					} else {
						for _, n := range field.Names {
							si.fields = append(si.fields, &Field{Name: n.Name, Type: typeStr})
						}
					}
				}
			}
			m[ts.Name.Name] = si
		}
	}
	return m
}

func buildTypeParamMap(file *ast.File) map[string]*typeParamInfo {
	m := make(map[string]*typeParamInfo)
	for _, decl := range file.Decls {
		gd, ok := decl.(*ast.GenDecl)
		if !ok {
			continue
		}
		for _, spec := range gd.Specs {
			ts, ok := spec.(*ast.TypeSpec)
			if !ok {
				continue
			}
			if ts.TypeParams == nil {
				continue
			}
			info := &typeParamInfo{}
			for _, field := range ts.TypeParams.List {
				constraint := TypeExprToString(field.Type)
				for _, name := range field.Names {
					info.names = append(info.names, name.Name)
					info.constraints = append(info.constraints, constraint)
				}
			}
			m[ts.Name.Name] = info
		}
	}
	return m
}

func parseFunction(fn *ast.FuncDecl, typeMap map[string]*structInfo, typeParamMap map[string]*typeParamInfo) *Function {
	f := &Function{
		Name: fn.Name.Name,
	}

	// Build type parameter substitution map for generic functions
	typeSubst := make(map[string]string)

	// Parse function-level type parameters
	if fn.Type.TypeParams != nil {
		for _, field := range fn.Type.TypeParams.List {
			constraint := TypeExprToString(field.Type)
			concreteType := resolveConstraintType(constraint)
			for _, name := range field.Names {
				typeSubst[name.Name] = concreteType
				f.TypeParams = append(f.TypeParams, concreteType)
			}
		}
	}

	// Parse receiver
	if fn.Recv != nil && len(fn.Recv.List) > 0 {
		recvField := fn.Recv.List[0]
		recv := &Receiver{}

		typeName, isPtr, origTypeParams := extractReceiverInfo(recvField.Type)
		recv.Type = typeName
		recv.IsPtr = isPtr

		if len(origTypeParams) > 0 {
			recv.IsGeneric = true
			recv.OrigTypeParamNames = origTypeParams

			// Look up the struct's type param constraints to get concrete types
			if tpInfo, ok := typeParamMap[typeName]; ok {
				for i, paramName := range origTypeParams {
					if i < len(tpInfo.constraints) {
						concreteType := resolveConstraintType(tpInfo.constraints[i])
						typeSubst[paramName] = concreteType
						f.TypeParams = append(f.TypeParams, concreteType)
					} else {
						// Fallback
						typeSubst[paramName] = "string"
						f.TypeParams = append(f.TypeParams, "string")
					}
				}
			} else {
				// Unknown struct, use defaults
				for _, paramName := range origTypeParams {
					typeSubst[paramName] = "string"
					f.TypeParams = append(f.TypeParams, "string")
				}
			}
		}

		// Get receiver variable name
		if len(recvField.Names) > 0 && recvField.Names[0].Name != "_" {
			recv.Name = recvField.Names[0].Name
		} else {
			if len(typeName) > 0 {
				recv.Name = strings.ToLower(string(typeName[0]))
			} else {
				recv.Name = "r"
			}
		}

		// Get struct fields (only for non-generic receivers)
		if !recv.IsGeneric {
			if si, ok := typeMap[typeName]; ok {
				recv.Fields = si.fields
			}
		}

		f.Receiver = recv
	}

	// Parse parameters
	if fn.Type.Params != nil {
		for _, field := range fn.Type.Params.List {
			isVariadic := false
			typeStr := ""
			if ve, ok := field.Type.(*ast.Ellipsis); ok {
				isVariadic = true
				typeStr = "[]" + substituteTypeParams(TypeExprToString(ve.Elt), typeSubst)
			} else {
				typeStr = substituteTypeParams(TypeExprToString(field.Type), typeSubst)
			}

			if len(field.Names) == 0 {
				f.Params = append(f.Params, &Param{
					Name:       "p",
					Type:       typeStr,
					IsVariadic: isVariadic,
				})
			} else {
				for _, name := range field.Names {
					f.Params = append(f.Params, &Param{
						Name:       name.Name,
						Type:       typeStr,
						IsVariadic: isVariadic,
					})
				}
			}
		}
	}

	// Parse return values
	if fn.Type.Results != nil {
		results := fn.Type.Results.List

		// Count error returns and non-error returns
		totalNonError := 0
		hasError := false
		for _, field := range results {
			typeStr := substituteTypeParams(TypeExprToString(field.Type), typeSubst)
			count := 1
			if len(field.Names) > 0 {
				count = len(field.Names)
			}
			for i := 0; i < count; i++ {
				if typeStr == "error" {
					hasError = true
				} else {
					totalNonError++
				}
			}
		}

		if hasError {
			if totalNonError == 0 {
				f.OnlyError = true
			} else {
				f.ReturnsErr = true
			}
		}

		retIdx := 0
		for _, field := range results {
			typeStr := substituteTypeParams(TypeExprToString(field.Type), typeSubst)
			isErr := typeStr == "error"

			if isErr {
				continue
			}

			if len(field.Names) == 0 {
				retName := returnName(retIdx, totalNonError, "")
				f.Returns = append(f.Returns, &ReturnValue{
					Name: retName,
					Type: typeStr,
				})
				retIdx++
			} else {
				for _, name := range field.Names {
					retName := returnName(retIdx, totalNonError, name.Name)
					f.Returns = append(f.Returns, &ReturnValue{
						Name: retName,
						Type: typeStr,
					})
					retIdx++
				}
			}
		}
	}

	return f
}

func returnName(idx, total int, namedReturn string) string {
	if namedReturn != "" {
		return "want" + strings.Title(namedReturn)
	}
	if total == 1 {
		return "want"
	}
	if idx == 0 {
		return "want"
	}
	return "want" + string(rune('0'+idx))
}

func extractReceiverInfo(expr ast.Expr) (typeName string, isPtr bool, typeParams []string) {
	switch t := expr.(type) {
	case *ast.StarExpr:
		name, _, params := extractReceiverInfo(t.X)
		return name, true, params
	case *ast.Ident:
		return t.Name, false, nil
	case *ast.IndexExpr:
		if id, ok := t.X.(*ast.Ident); ok {
			paramName := TypeExprToString(t.Index)
			return id.Name, false, []string{paramName}
		}
	case *ast.IndexListExpr:
		if id, ok := t.X.(*ast.Ident); ok {
			var params []string
			for _, idx := range t.Indices {
				params = append(params, TypeExprToString(idx))
			}
			return id.Name, false, params
		}
	}
	return "", false, nil
}

func resolveConstraintType(constraint string) string {
	switch constraint {
	case "any":
		return "int"
	case "comparable":
		return "string"
	}
	if strings.HasPrefix(constraint, "~") {
		return resolveConstraintType(constraint[1:])
	}
	if strings.Contains(constraint, " | ") {
		parts := strings.SplitN(constraint, " | ", 2)
		return resolveConstraintType(strings.TrimSpace(parts[0]))
	}
	// Known primitives
	switch constraint {
	case "int", "int8", "int16", "int32", "int64",
		"uint", "uint8", "uint16", "uint32", "uint64",
		"float32", "float64", "complex64", "complex128",
		"bool", "string", "byte", "rune", "uintptr":
		return constraint
	}
	// Unknown named interface → string
	return "string"
}

func substituteTypeParams(typeStr string, subst map[string]string) string {
	if len(subst) == 0 {
		return typeStr
	}
	for paramName, concreteType := range subst {
		typeStr = replaceTypeParam(typeStr, paramName, concreteType)
	}
	return typeStr
}

func replaceTypeParam(typeStr, paramName, concreteType string) string {
	result := ""
	remaining := typeStr
	for len(remaining) > 0 {
		idx := strings.Index(remaining, paramName)
		if idx == -1 {
			result += remaining
			break
		}
		if idx > 0 && isIdentChar(remaining[idx-1]) {
			result += remaining[:idx+len(paramName)]
			remaining = remaining[idx+len(paramName):]
			continue
		}
		afterIdx := idx + len(paramName)
		if afterIdx < len(remaining) && isIdentChar(remaining[afterIdx]) {
			result += remaining[:idx+len(paramName)]
			remaining = remaining[idx+len(paramName):]
			continue
		}
		result += remaining[:idx] + concreteType
		remaining = remaining[afterIdx:]
	}
	return result
}

func isIdentChar(c byte) bool {
	return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9') || c == '_'
}

// TypeExprToString converts an AST type expression to its string representation
func TypeExprToString(expr ast.Expr) string {
	switch t := expr.(type) {
	case *ast.Ident:
		return t.Name
	case *ast.StarExpr:
		return "*" + TypeExprToString(t.X)
	case *ast.ArrayType:
		if t.Len == nil {
			return "[]" + TypeExprToString(t.Elt)
		}
		return "[" + arrayLenString(t.Len) + "]" + TypeExprToString(t.Elt)
	case *ast.MapType:
		return "map[" + TypeExprToString(t.Key) + "]" + TypeExprToString(t.Value)
	case *ast.SelectorExpr:
		return TypeExprToString(t.X) + "." + t.Sel.Name
	case *ast.InterfaceType:
		if t.Methods == nil || len(t.Methods.List) == 0 {
			return "interface{}"
		}
		return "interface{...}"
	case *ast.FuncType:
		return funcTypeToString(t)
	case *ast.ChanType:
		switch t.Dir {
		case ast.SEND:
			return "chan<- " + TypeExprToString(t.Value)
		case ast.RECV:
			return "<-chan " + TypeExprToString(t.Value)
		default:
			return "chan " + TypeExprToString(t.Value)
		}
	case *ast.Ellipsis:
		return "..." + TypeExprToString(t.Elt)
	case *ast.IndexExpr:
		return TypeExprToString(t.X) + "[" + TypeExprToString(t.Index) + "]"
	case *ast.IndexListExpr:
		parts := make([]string, len(t.Indices))
		for i, idx := range t.Indices {
			parts[i] = TypeExprToString(idx)
		}
		return TypeExprToString(t.X) + "[" + strings.Join(parts, ", ") + "]"
	case *ast.StructType:
		return structTypeToString(t)
	case *ast.BinaryExpr:
		return TypeExprToString(t.X) + " | " + TypeExprToString(t.Y)
	case *ast.UnaryExpr:
		return "~" + TypeExprToString(t.X)
	}
	return ""
}

func arrayLenString(expr ast.Expr) string {
	switch t := expr.(type) {
	case *ast.BasicLit:
		return t.Value
	case *ast.Ident:
		return t.Name
	}
	return "..."
}

func funcTypeToString(ft *ast.FuncType) string {
	var sb strings.Builder
	sb.WriteString("func(")
	if ft.Params != nil {
		first := true
		for _, field := range ft.Params.List {
			typeStr := TypeExprToString(field.Type)
			if len(field.Names) == 0 {
				if !first {
					sb.WriteString(", ")
				}
				sb.WriteString(typeStr)
				first = false
			} else {
				for _, name := range field.Names {
					if !first {
						sb.WriteString(", ")
					}
					sb.WriteString(name.Name)
					sb.WriteString(" ")
					sb.WriteString(typeStr)
					first = false
				}
			}
		}
	}
	sb.WriteString(")")
	if ft.Results != nil && len(ft.Results.List) > 0 {
		if len(ft.Results.List) == 1 && len(ft.Results.List[0].Names) == 0 {
			sb.WriteString(" ")
			sb.WriteString(TypeExprToString(ft.Results.List[0].Type))
		} else {
			sb.WriteString(" (")
			first := true
			for _, field := range ft.Results.List {
				typeStr := TypeExprToString(field.Type)
				count := 1
				if len(field.Names) > 0 {
					count = len(field.Names)
				}
				for i := 0; i < count; i++ {
					if !first {
						sb.WriteString(", ")
					}
					sb.WriteString(typeStr)
					first = false
				}
			}
			sb.WriteString(")")
		}
	}
	return sb.String()
}

func structTypeToString(st *ast.StructType) string {
	var sb strings.Builder
	sb.WriteString("struct{")
	if st.Fields != nil {
		fields := []string{}
		for _, field := range st.Fields.List {
			typeStr := TypeExprToString(field.Type)
			if len(field.Names) == 0 {
				fields = append(fields, typeStr)
			} else {
				names := make([]string, len(field.Names))
				for i, n := range field.Names {
					names[i] = n.Name
				}
				fields = append(fields, strings.Join(names, ", ")+" "+typeStr)
			}
		}
		sb.WriteString(strings.Join(fields, "; "))
	}
	sb.WriteString("}")
	return sb.String()
}
