# Now I need to update the render.go to use OrigType when useTestify is true
# and the function has type params

# The key places to update:
# 1. Test struct fields: use OrigType instead of Type for params/returns when testify
# 2. Receiver in test struct: use OrigTypeParamNames instead of TypeParams when testify
# 3. Function call: don't include type params when testify
# 4. Receiver init: use OrigTypeParamNames instead of TypeParams when testify

# This is quite a lot of changes. Let me add a helper function to get
# the type to use (either Type or OrigType based on testify setting)

# Actually, looking at this more carefully - I think the cleanest approach is:
# When rendering for testify, use OrigType for everything related to generic params.
# 
# Let me update the render to use an "effective type" approach.
# I'll add helper functions to renderTestFunc that use OrigType for testify.

# First, let me understand how the Function structure works for testify:
# For `func EqualCheck[T comparable](a, b T) bool`:
# - fn.TypeParams = ["string"] (concrete type for T)  
# - fn.Params[0].Type = "string" (substituted), OrigType = "T"
# - fn.Params[1].Type = "string" (substituted), OrigType = "T"
# - fn.Returns[0].Type = "bool", OrigType = "bool" (not a type param)

# For testify, we want:
# - Params use OrigType: "T"
# - Function call: "EqualCheck(tt.args.a, tt.args.b)" (no type params)
# - Test struct receiver: "*Set[T]" instead of "*Set[string]"

# I'll update renderTestFunc to accept a flag and use different types

cat > /tmp/update_render_testify.py << 'EOF'
with open('/workspace/gotests/internal/render/render.go', 'r') as f:
    content = f.read()

# Add a function to get effective param type
old_func = '''// funcCallPrefix returns the function name prefix for error message format strings with args'''

new_func = '''// effectiveParamType returns the type to use for a parameter (OrigType for testify, Type otherwise)
func effectiveParamType(p *input.Param, useTestify bool) string {
	if useTestify && p.OrigType != "" && p.OrigType != p.Type {
		return p.OrigType
	}
	return p.Type
}

// effectiveReturnType returns the type to use for a return value
func effectiveReturnType(ret *input.ReturnValue, useTestify bool) string {
	if useTestify && ret.OrigType != "" && ret.OrigType != ret.Type {
		return ret.OrigType
	}
	return ret.Type
}

// effectiveReceiverTypeStr returns the receiver type string including type params
func effectiveReceiverTypeStr(fn *input.Function, useTestify bool) string {
	if fn.Receiver == nil {
		return ""
	}
	typeName := fn.Receiver.Type
	if fn.Receiver.IsGeneric && len(fn.Receiver.OrigTypeParamNames) > 0 {
		if useTestify {
			typeName += "[" + strings.Join(fn.Receiver.OrigTypeParamNames, ", ") + "]"
		} else if len(fn.TypeParams) > 0 {
			typeName += "[" + strings.Join(fn.TypeParams, ", ") + "]"
		}
	}
	return typeName
}

// effectiveCallExpr returns the function call expression (uses original type params for testify)
func effectiveCallExpr(fn *input.Function, recvVar string, useTestify bool) string {
	var sb strings.Builder
	if fn.Receiver != nil {
		sb.WriteString(recvVar)
		sb.WriteString(".")
		sb.WriteString(fn.Name)
	} else {
		sb.WriteString(fn.Name)
		if !useTestify && len(fn.TypeParams) > 0 {
			sb.WriteString("[")
			sb.WriteString(strings.Join(fn.TypeParams, ", "))
			sb.WriteString("]")
		}
	}
	sb.WriteString("(")
	for i, p := range fn.Params {
		if i > 0 {
			sb.WriteString(", ")
		}
		sb.WriteString("tt.args.")
		sb.WriteString(p.Name)
		if p.IsVariadic {
			sb.WriteString("...")
		}
	}
	sb.WriteString(")")
	return sb.String()
}

// funcCallPrefix returns the function name prefix for error message format strings with args'''

if old_func in content:
    content = content.replace(old_func, new_func)
    print("Added helper functions")
else:
    print("Pattern not found")

with open('/workspace/gotests/internal/render/render.go', 'w') as f:
    f.write(content)
EOF
python3 /tmp/update_render_testify.py

